\sigma_{zz}=\frac{\mu}{k}\Bigl[\psi'''-3k^{2}\psi'\Bigr]\cos kx .
\end{equation*}
On the free surface $\psi'(0)=0$,
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}\psi'''(0)\cos kx
          =\frac{2\mu k^{2}B}{k}\cos kx =\rho ge(t)\cos kx ,
\end{equation*}
i.e.

\begin{equation*}
e(t)=\frac{2\mu k}{\rho g}B ,\qquad 
\psi'''(0)=2k^{2}B , 
\end{equation*}
and the zero normal stress at the base,
$\sigma_{zz}(h)=0$, is
\begin{equation*}
\psi'''(h)=3k^{2}\psi'(h)\iff
B\,C_{h}=kh\bigl(BS_{h}+DC_{h}\bigr) .
\end{equation*}
The basal shear traction is

\begin{equation*}
\sigma_{xz}=\mu\bigl[\psi''+k^{2}\psi\bigr]\sin kx ,
\end{equation*}
so that with $\tau_{b}=S_{0}\sin kx$

\begin{equation*}
\mu\Bigl[\psi''(h)+k^{2}\psi(h)\Bigr]=S_{0}.
\end{equation*}
Writing $D$ from the zero normal stress condition as
\begin{equation*}
D=B\,\frac{C_{h}-khS_{h}}{khC_{h}},
\end{equation*}
the shear condition gives

\begin{equation*}
2\mu k\, \frac{B}{khC_{h}}\,
\Bigl[k^{2}h^{2}+C_{h}^{2}\Bigr]=S_{0},
\end{equation*}
i.e.

\begin{equation*}
B=\frac{S_{0}hC_{h}}{2\mu\Bigl[k^{2}h^{2}+C_{h}^{2}\Bigr]} .
\end{equation*}
Hence the steady free surface is

\begin{equation*}
e_{s}=\frac{2\mu k}{\rho g}B
     =\frac{S_{0}}{\rho g}\;
       \frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}\;,
\end{equation*}
