3.text:
In the $x\!-\!z$ plane put $\psi(x,z)=f(z)\sin kx$,

\begin{equation*}
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx,
\end{equation*}
so that with $(D^{2}-k^{2})^{2}f=0$

\begin{equation*}
u_{x}(0)=0\;\Longleftrightarrow\;f'(0)=0,
\qquad 
\dot e=u_{z}(0)=-kf(0)\cos kx ,
\end{equation*}
and in the steady state $f(0)=0$.  With

\begin{equation*}
P(z)=-\frac{\mu}{k}\Big[f'''-k^{2}f'\Big],\qquad 
\sigma_{zz}=\Big[\frac{\mu}{k}f'''-3\mu kf'\Big]\cos kx ,
\qquad 
\sigma_{xz}=\mu\Big[f''+k^{2}f\Big]\sin kx ,
\end{equation*}
the top free surface is

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
            =\rho g\,e(t)\cos kx ,\qquad f'(0)=0,
\end{equation*}
and the free base is
\begin{equation*}
\sigma_{zz}(h)=0\;\Longleftrightarrow\;f'''(h)=3k^{2}f'(h),\qquad
\sigma_{xz}(h)=S_{0}\sin kx .
\end{equation*}
With $f(0)=f'(0)=0$
\begin{equation*}
f(z)=C_{1}\big[\sinh kz-kz\cosh kz\big]+C_{3}z\sinh kz ,
\end{equation*}
and $f'''(h)=3k^{2}f'(h)$ gives
\begin{equation*}
C_{3}=C_{1}\frac{kh\sinh kh-\cosh kh}{h\cosh kh}\; .
\end{equation*}
The basal shear
\begin{equation*}
\mu\big[f''+k^{2}f\big]_{h}=S_{0}
\end{equation*}
gives
\begin{equation*}
C_{1}=-\frac{S_{0}h\cosh kh}
            {2\mu k\Big[\cosh^{2}kh+k^{2}h^{2}\Big]},\qquad
C_{3}=-\frac{S_{0}\big(kh\sinh kh-\cosh kh\big)}
            {2\mu k\Big[\cosh^{2}kh+k^{2}h^{2}\Big]} .
\end{equation*}
Now $f'''(0)=-2k^{3}C_{1}$ and
\begin{equation*}
\rho g e_{s}= \frac{\mu}{k}f'''(0)=-2\mu k^{2}C_{1}
           =\frac{S_{0}kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}} .
\end{equation*}
Hence with the isostatic restoring stress $\Delta\rho g$,
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\chi(kh),\qquad 
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{\cosh kh}{kh}+\frac{kh}{\cosh kh}\Bigg]^{-1},
\end{equation*}
the sign being the $\sin kx\leftrightarrow\cos kx$ $90^{\circ}$ phase.
The viscosity drops out of the steady state.  In the long-wave
lubrication limit $kh\ll1$, $\cosh kh=1+O(k^{2}h^{2})$,
\begin{equation*}
\chi(kh)=kh\Big[1+O(k^{2}h^{2})\Big],\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
i.e. $|e_{s}|\approx kh\,S_{0}/\Delta\rho g$ and for the usual
geodynamic $kh\sim O(1)$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.45\!-\!0.5$.
Up to the conventional sign $e_{s}=-\chi S_{0}/\Delta\rho g$ this is
the familiar $e_{s}\propto kh\,S_{0}/\Delta\rho g$ viscous dynamic
topography produced by a harmonic basal shear $S_{0}\sin kx$.  With the
$\rho$ notation of the statement the same expression is
$e_{s}= \chi S_{0}/\rho g$ with the $\chi$ above, $\rho\to\Delta\rho$
for the buoyancy restoring force. ∎

reflection_text.3:
In the $x\!-\!z$ plane put $\psi(x,z)=f(z)\sin kx$,

\begin{equation*}
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx,
\end{equation*}
so that with $(D^{2}-k^{2})^{2}f=0$

\begin{equation*}
u_{x}(0)=0\;\Longleftrightarrow\;f'(0)=0,
\qquad 
\dot e=u_{z}(0)=-kf(0)\cos kx ,
\end{equation*}
and in the steady state $f(0)=0$.  With

\begin{equation*}
P(z)=-\frac{\mu}{k}\Big[f'''-k^{2}f'\Big],\qquad 
\sigma_{zz}=\Big[\frac{\mu}{k}f'''-3\mu kf'\Big]\cos kx ,
\qquad 
\sigma_{xz}=\mu\Big[f''+k^{2}f\Big]\sin kx ,
\end{equation*}
the top free surface is

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
            =\rho g\,e(t)\cos kx ,\qquad f'(0)=0,
\end{equation*}
and the free base is
\begin{equation*}
\sigma_{zz}(h)=0\;\Longleftrightarrow\;f'''(h)=3k^{2}f'(h),\qquad
\sigma_{xz}(h)=S_{0}\sin kx .
\end{equation*}
With $f(0)=f'(0)=0$
\begin{equation*}
f(z)=C_{1}\big[\sinh kz-kz\cosh kz\big]+C_{3}z\sinh kz ,
\end{equation*}
and $f'''(h)=3k^{2}f'(h)$ gives
\begin{equation*}
C_{3}=C_{1}\frac{kh\sinh kh-\cosh kh}{h\cosh kh}\; .
\end{equation*}
The basal shear
\begin{equation*}
\mu\big[f''+k^{2}f\big]_{h}=S_{0}
\end{equation*}
gives
\begin{equation*}
C_{1}=-\frac{S_{0}h\cosh kh}
            {2\mu k\Big[\cosh^{2}kh+k^{2}h^{2}\Big]},\qquad
C_{3}=-\frac{S_{0}\big(kh\sinh kh-\cosh kh\big)}
            {2\mu k\Big[\cosh^{2}kh+k^{2}h^{2}\Big]} .
\end{equation*}
Now $f'''(0)=-2k^{3}C_{1}$ and
\begin{equation*}
\rho g e_{s}= \frac{\mu}{k}f'''(0)=-2\mu k^{2}C_{1}
           =\frac{S_{0}kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}} .
\end{equation*}
Hence with the isostatic restoring stress $\Delta\rho g$,
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\chi(kh),\qquad 
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{\cosh kh}{kh}+\frac{kh}{\cosh kh}\Bigg]^{-1},
\end{equation*}
the sign being the $\sin kx\leftrightarrow\cos kx$ $90^{\circ}$ phase.
The viscosity drops out of the steady state.  In the long-wave
lubrication limit $kh\ll1$, $\cosh kh=1+O(k^{2}h^{2})$,
\begin{equation*}
\chi(kh)=kh\Big[1+O(k^{2}h^{2})\Big],\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
i.e. $|e_{s}|\approx kh\,S_{0}/\Delta\rho g$ and for the usual
geodynamic $kh\sim O(1)$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.45\!-\!0.5$.
Up to the conventional sign $e_{s}=-\chi S_{0}/\Delta\rho g$ this is
the familiar $e_{s}\propto kh\,S_{0}/\Delta\rho g$ viscous dynamic
topography produced by a harmonic basal shear $S_{0}\sin kx$.  With the
$\rho$ notation of the statement the same expression is
$e_{s}= \chi S_{0}/\rho g$ with the $\chi$ above, $\rho\to\Delta\rho$
for the buoyancy restoring force. ∎

12.text:
With the stream function $\psi (x,z)=F(z)\sin kx$

\begin{equation*}
u_{x}=F'\sin kx ,\qquad u_{z}=-kF\cos kx ,\qquad 
\nabla^{4}\psi=0,
\end{equation*}

\begin{equation*}
F(z)=\big(a_{0}+a_{1}z\big)\cosh kz+\big(b_{0}+b_{1}z\big)\sinh kz,
\end{equation*}

and

\begin{equation*}
\sigma_{xz}= \mu\big[F''+k^{2}F\big]\sin kx ,
\qquad 
\sigma_{zz}= \mu k^{-1}\!\left[F'''-3k^{2}F'\right]\cos kx .
\end{equation*}

On the free rigid lid $z=0$

\begin{equation*}
u_{x}(0)=0\iff F'(0)=0,\qquad 
u_{z}(0)=\dot e\cos kx ,
\end{equation*}
so that in the steady state $\dot e=0$ 

\begin{equation*}
F(0)=0,\qquad F'(0)=0 .
\end{equation*}

Hence $a_{0}=0$ and $a_{1}=-k b_{0}$ and

\begin{equation*}
F(z)=b_{0}\Big[-k z\cosh kz+\sinh kz\Big]
     +\big(b_{1}z\cosh kz+b_{1}z\sinh kz\big) .
\end{equation*}

Free surface normal stress

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}F'''(0)\cos kx =\rho g e\cos kx ,
\end{equation*}

and $F'''(0)=-2k^{3}b_{0}$ gives

\begin{equation*}
b_{0}=-\frac{\rho g e}{2\mu k^{2}},\qquad 
a_{1}= \frac{\rho g e}{2\mu k},
\end{equation*}

so that the top normal stress is viscosity independent.  

The stress free base $\sigma_{zz}(h)=0$ is

\begin{equation*}
F'''(h)=3k^{2}F'(h) ,
\end{equation*}

i.e.

\begin{equation*}
b_{1}=b_{0}\Big[\,k\tanh kh-\frac1{h}\Big] ,
\end{equation*}

and the imposed basal shear

\begin{equation*}
\sigma_{xz}(h)=S_{0}\sin kx
\end{equation*}

is

\begin{equation*}
\mu\big[F''+k^{2}F\big]_{h}=S_{0}.
\end{equation*}

With $C=\cosh kh$, $S=\sinh kh$

\begin{equation*}
F''+k^{2}F\big|_{h}=2k\Big[b_{1}C+kh\big(-k b_{0}C+b_{1}S\big)\Big],
\end{equation*}

so that with the $b_{1}$ above

\begin{equation*}
2k\mu b_{0}\frac{k^{2}h^{2}+C^{2}}{kh C}= -S_{0}.
\end{equation*}

Eliminating $b_{0}$ with $b_{0}=-\rho g e/2\mu k^{2}$ gives the
viscosity independent steady balance

\begin{equation*}
\rho g e\,\frac{C^{2}+k^{2}h^{2}}{khC}=S_{0},
\end{equation*}

i.e. with the buoyancy restoring stress $\Delta\rho g e$,
$\rho\to\Delta\rho$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
       \frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
     \equiv \chi(kh)\frac{S_{0}}{\Delta\rho g} ,
\end{equation*}

\begin{equation*}
\;\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
        =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}\;
\end{equation*}

up to the $90^{\circ}$ $\sin kx\leftrightarrow\cos kx$ phase shift,
$e_{s}\propto -\,\chi S_{0}/\Delta\rho g$ with the sign convention
used above.  In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad 
\chi\simeq kh\;\;{\rm for}\;kh\ll1,
\end{equation*}

and $\chi\sim2kh\,e^{-kh}$ for $kh\gg1$.  For $kh=1$,
$\chi\approx0.46$, the familiar $O(kh)$ viscous dynamic topography
$e_{s}\approx kh\,S_{0}/\Delta\rho g$.  The $kh\sinh kh/[\sinh kh
\cosh kh-kh]$ forms obtained by Colleagues 3, 11, 14 follow from the
additional impermeable condition $F(h)=0$, i.e. $u_{z}(h)=0$, which is
not imposed by the statement $\sigma_{zz}(h)=0$.  With the stress free
base as stated the cosh numerator form above is the correct steady,
viscosity independent amplitude, often quoted in the long wave limit
as $e_{s}\approx kh\,S_{0}/\Delta\rho g$.  The minus sign is the
conventional $90^{\circ}$ phase between the $\sin kx$ basal shear and
the $\cos kx$ topography. ∎

5.text:
In the harmonic $ \sin kx\; \cos kx$ sector write with $a=k$
$\psi =F(z)\sin kx$, $u_{x}=F'\sin kx$, $u_{z}=-aF\cos kx$,
$\nabla^{4}\psi=0$,

\begin{equation*}
F^{(iv)}-2a^{2}F''+a^{4}F=0 ,\qquad 
F(z)=(p_{0}+p_{1}z)\cosh az+(q_{0}+q_{1}z)\sinh az ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\big[F''+a^{2}F\big]\sin kx,\qquad
\sigma_{zz}= \mu\Big[a^{-1}F'''-3aF'\Big]\cos kx .
\end{equation*}
On the free top $u_{x}(0)=0$ gives $F'(0)=0$ and in the steady state
$\dot e=u_{z}(0)=0$ gives $F(0)=0$.  Up to the $\sin\leftrightarrow\cos$
phase we may put

\begin{equation*}
F(0)=F'(0)=0,\qquad 
F(z)=C_{1}\sinh az+C_{3}z\sinh az-aC_{1}z\cosh az ,
\end{equation*}
so that

\begin{align*}
F'+a^{2}&\;:\;F''+a^{2}F=2a\Big[C_{3}\cosh az+C_{3}az\sinh az
        -a^{2}C_{1}z\cosh az\Big],\\
F'''&=3C_{3}a^{2}\sinh az+C_{3}a^{3}z\cosh az
      -2a^{3}C_{1}\cosh az-a^{4}C_{1}z\sinh az .
\end{align*}
Hence

\begin{equation*}
\sigma_{zz}(0)=\mu a^{-1}F'''(0)\cos kx
              =-2\mu a^{2}C_{1}\cos kx ,\qquad 
\rho g e_{s}=-2\mu a^{2}C_{1},
\end{equation*}
and the traction free base $\sigma_{zz}(h)=0$ is $F'''(h)=3a^{2}F'(h)$,
i.e.

\begin{equation*}
C_{1}=C_{3}h\cosh ah\Big/[ah\sinh ah-\cosh ah\Big] .
\end{equation*}
The imposed basal shear $\sigma_{xz}(h)=S_{0}\sin kx$ is

\begin{equation*}
\mu\big[F''(h)+a^{2}F(h)\big]=S_{0},
\end{equation*}
i.e.

\begin{equation*}
2a\Big[C_{3}\cosh ah+C_{3}ah\sinh ah-a^{2}C_{1}h\cosh ah\Big]
      =\frac{S_{0}}{\mu}\; .
\end{equation*}
Eliminating $C_{1}$,

\begin{equation*}
C_{3}= -\,\frac{S_{0}\big[ah\sinh ah-\cosh ah\big]}
             {2\mu a\big[\cosh^{2}ah+a^{2}h^{2}\big]},\qquad
C_{1}= -\,\frac{S_{0}h\cosh ah}
             {2\mu a\big[\cosh^{2}ah+a^{2}h^{2}\big]} ,
\end{equation*}
and with the free surface balance $\sigma_{zz}(0)=\rho g e_{s}\cos kx$

\begin{equation*}
\rho g e_{s}= -2\mu a^{2}C_{1}
           =\frac{S_{0}\,ah\cosh ah}{\cosh^{2}ah+a^{2}h^{2}} .
\end{equation*}
With the isostatic restoring stress $\Delta\rho g$,
$\rho\to\Delta\rho$,

\begin{equation*}
e_{s}= \chi(a h)\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(a h)=\frac{ah\cosh ah}{\cosh^{2}ah+a^{2}h^{2}}
        =\Big[\frac{ah}{\cosh ah}+\frac{\cosh ah}{ah}\Big]^{-1},
\end{equation*}
the sign being the $90^{\circ}$ $\sin kx\leftrightarrow\cos kx$
phase shift.  The viscosity drops out of the steady state.  In the
long wave limit $m=ah\ll1$, $\cosh m=1+O(m^{2})$,

\begin{equation*}
\chi(m)=\frac{m}{1+m^{2}}+O(m^{3})\simeq m,
\qquad e_{s}\simeq \frac{kh}{\Delta\rho g}S_{0},
\end{equation*}
and for the geologically relevant $m=O(1)$, e.g. $m=1$,
$\chi(1)=\cosh1/[\,1+\cosh^{2}1\,]\approx0.46$.  This is the
viscosity–independent viscous dynamic topography of a Stokes layer
with $u_{x}(0)=0$, $\sigma_{zz}(0)=\Delta\rho g e\cos kx$ on the top
and $\sigma_{zz}(h)=0$, $\sigma_{xz}(h)=S_{0}\sin kx$ on the base.
The forms with a $\sinh$ numerator, $\chi\propto m\sinh m/
\big[\sinh m\cosh m-m\big]$, are obtained if an extra impermeable
condition $u_{z}(h)=0$, $F(h)=0$, is imposed at the base.  With the
boundary conditions stated the transfer function is the
$\,m\cosh m/[\cosh^{2}m+m^{2}]$ function above, essentially
$|e_{s}|\sim kh\,S_{0}/\Delta\rho g$ in the lubrication limit.  Up to
the conventional sign $e_{s}=-\chi S_{0}/\Delta\rho g$ the magnitude
is the expression quoted. ∎

7.text:
PUBLIC RESPONSE: With the harmonic mode $\psi(x,z)=f(z)\sin kx$,
$u_x=f'\sin kx$, $u_z=-k f\cos kx$, $\nabla^{4}\psi =0$ and
\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx,\qquad
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
the rigid lid is $u_x(0)=0$, $f'(0)=0$, and in the steady state
$u_z(0)=0$, $f(0)=0$.  Hence, up to the conventional sign,
\begin{equation*}
f(z)=\big[Bz+ D z\big]\sinh kz+Bz\cosh kz ,
\qquad f(0)=f'(0)=0,
\end{equation*}
and with $C=-B/k$ the four constants can be written as
$f(z)=Bz\cosh kz+C\sinh kz+Dz\sinh kz$.
The normal stress free base is
$\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h)$,
i.e.
\begin{equation*}
Bh\sinh kh+C\cosh kh+Dh\cosh kh=0,
\end{equation*}
so that with $C=-B/k$
\begin{equation*}
D=B\Big[\frac{1}{kh}-\tanh kh\Big] ,
\end{equation*}
and the impermeable base in the steady state is $f(h)=0$.  The basal
shear is
\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0},
\end{equation*}
i.e.
\begin{equation*}
2\mu k\Big[Bh k\cosh kh+D\cosh kh+Dh k\sinh kh\Big]=S_{0}.
\end{equation*}
Eliminating $D$ gives
\begin{equation*}
B= -\frac{S_{0}h}{2\mu k}\,
\frac{\sinh kh}{\cosh^{2}kh+k^{2}h^{2}} .
\end{equation*}
On the free surface $f'(0)=0$ so that
$\sigma_{zz}(0)=\mu f'''(0)k^{-1}\cos kx$ and
$f'''(0)=2k^{2}B$.  Hence
\begin{equation*}
\rho g e_{s}\cos kx =\frac{\mu}{k}f'''(0)\cos kx
 =\frac{2\mu k B}{\,}\cos kx,
\end{equation*}
and with the buoyancy restoring stress $\Delta\rho g e$,
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{k h\,\sinh kh}{\cosh^{2}kh+k^{2}h^{2}} ,
\end{equation*}
i.e. in the notation $e_{s}=\chi S_{0}/\Delta\rho g$
\begin{equation*}
\chi(kh)=\frac{k h\,\sinh(kh)}{\cosh^{2}(kh)+(kh)^{2}} .
\end{equation*}
The viscosity cancels as it must for the steady Stokes problem.
For $kh\ll1$, $\sinh kh=kh+O[(kh)^{3}]$, $\cosh kh=1+O[(kh)^{2}]$, so
$\chi=kh\,[1+O[(kh)^{2}]]$, the familiar lubrication scaling
$e_{s}\simeq kh\,S_{0}/\Delta\rho g$ with the $90^{\circ}$ $\sin/\cos$
phase shift between the imposed basal shear and the topographic cosine.
This is the $t\to\infty$ viscous dynamic topography and coincides with
the form quoted by the stream-function evaluations that keep the
pressure continuity $P(z)=-(\mu/k)[f'''-k^{2}f']$ together with the
steady kinematic condition $f(0)=f(h)=0$.  Up to the conventional
sign the magnitude is the expression above; with $\rho\to\Delta\rho$
it is the usual $e_{s}= \chi S_{0}/\Delta\rho g$ law.

3.text:
With the stream function $\psi=f(z)\sin kx$

\begin{equation*}
u_{x}=f'\sin kx,\qquad u_{z}=-k f\cos kx,\qquad 
\nabla^{4}\psi=0 ,
\end{equation*}
so that with $D=d/dz$
$(D^{2}-k^{2})^{2}f=0$.
On the free top $u_{x}(0)=0$ and in the steady state
$\dot e=u_{z}(0)=0$ so that

\begin{equation*}
f(0)=0,\qquad f'(0)=0,
\end{equation*}
and with $p=P(z)\cos kx$

\begin{equation*}
P=-\frac{\mu}{k}\Big[f'''-k^{2}f'\Big],\qquad 
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx,
\end{equation*}
\begin{equation*}
\sigma_{zz}=\Big[\frac{\mu}{k}f'''-3\mu k f'\Big]\cos kx .
\end{equation*}
Hence on $z=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\rho g\,e(t)\cos kx,
\qquad f'(0)=0,
\end{equation*}
and on the free base $z=h$

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad 
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0} .
\end{equation*}
With $f(0)=f'(0)=0$

\begin{equation*}
f(z)=Bz\cosh kz+Dz\sinh kz-\frac{B}{k}\sinh kz ,
\end{equation*}
so that
\begin{equation*}
f'(z)=kBz\sinh kz+D\sinh kz+kDz\cosh kz,
\end{equation*}
and
\begin{equation*}
f'''(z)=2k^{2}B\cosh kz+k^{3}Bz\sinh kz
       +3k^{2}D\sinh kz+k^{3}Dz\cosh kz .
\end{equation*}
$f'''(h)=3k^{2}f'(h)$ gives

\begin{equation*}
B\big[\cosh kh-kh\sinh kh\big]=khD\cosh kh ,
\end{equation*}
and with $c_{h}=\cosh kh$, $s_{h}=\sinh kh$,

\begin{equation*}
f''+k^{2}f=2k\Big[kBh\cosh kz+D\cosh kz
           +kDh\sinh kz\Big],
\end{equation*}
so that the basal shear

\begin{equation*}
\mu\big[f''+k^{2}f\big]_{h}=S_{0}
\end{equation*}
becomes

\begin{equation*}
2\mu k\Big[kBh\,c_{h}+D c_{h}+kDh s_{h}\Big]=S_{0}.
\end{equation*}
Eliminating $D$,

\begin{equation*}
D=B\,\frac{c_{h}-kh\,s_{h}}{kh\,c_{h}},\qquad
B=\frac{S_{0}h\,c_{h}}{2\mu\big[k^{2}h^{2}+c_{h}^{2}\big]} .
\end{equation*}
Now

\begin{equation*}
f'''(0)=2k^{2}B,\qquad 
\frac{\mu}{k}f'''(0)=\rho g e_{s},
\end{equation*}
hence in the steady state

\begin{equation*}
\rho g e_{s}=2\mu kB
          =\frac{S_{0}kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\end{equation*}
i.e. with the isostatic buoyancy $\Delta\rho g$ the normal stress
balance $\sigma_{zz}(0)=\Delta\rho g e\cos kx$ gives

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}\equiv
\chi(kh)\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
up to the $ \sin kx\leftrightarrow\cos kx$ $90^{\circ}$ phase,
conventionally written with the opposite sign.  In closed form

\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
       =\Bigg[\frac{\cosh kh}{kh}+\frac{kh}{\cosh kh}\Bigg]^{-1},
\end{equation*}
the viscosity dropping out of the steady state.  In particular

\begin{equation*}
\chi(kh)=kh\Big[1+O(k^{2}h^{2})\Big],\qquad kh\ll1,
\end{equation*}
so that in the usual long-wave lubrication limit

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad 
|e_{s}|\approx \chi_{0}\frac{S_{0}}{\Delta\rho g},\;\;
\chi_{0}\approx kh,
\end{equation*}
and for $kh=O(1)$ e.g. $kh=1$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.45\!-\!0.5$.  With the sign
convention $e_{s}>0$ upward this is $e_{s}=-\chi S_{0}/\Delta\rho g$
because the topography is $90^{\circ}$ out of phase with the imposed
$\sin kx$ basal shear.  The $\rho\to\Delta\rho$ replacement gives the
quoted form $e_{s}=\chi S_{0}/\rho g$ with the $\chi$ above.  This is the
familiar $e_{s}\propto kh\,S_{0}/\Delta\rho g$ viscous dynamic topography
produced by a harmonic basal traction. ∎

8.text:
With the $k$-mode

\begin{equation*}
\psi (x,z)=f(z)\sin kx,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu \big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}=\mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
and $(D^{2}-k^{2})^{2}f=0$.  On the material free surface

\begin{equation*}
u_{x}(0)=0\iff f'(0)=0,\qquad 
u_{z}(0)=\dot e\cos kx\iff f(0)=-\dot e/k ,
\end{equation*}
so that in the steady state $f(0)=0,\;f'(0)=0$ and

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\rho g e\cos kx ,
\qquad f'''(0)=\frac{k\rho g}{\mu}e .
\tag{1}
\end{equation*}
Put

\begin{equation*}
f(z)=a z\cosh kz+\big(Dz-a/k\big)\sinh kz ,
\end{equation*}
so that $f(0)=f'(0)=0$.  Then

\begin{equation*}
f'''(0)=2a k^{2},\qquad 
f'(z)=\big(akz+D\big)\sinh kz+Dkz\cosh kz ,
\end{equation*}
and with $\sigma_{zz}(h)=0$

\begin{equation*}
f'''(h)=3k^{2}f'(h)\Longleftrightarrow 
a\cosh kh=k h\big(a\sinh kh+D\cosh kh\big) ,
\end{equation*}
i.e.

\begin{equation*}
D=a\Big[\frac{1}{kh}-\tanh kh\Big]
   =a\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh}\; .
\tag{2}
\end{equation*}
Now

\begin{equation*}
f''+k^{2}f=2k\Big[akz\cosh kz+D\cosh kz+Dkz\sinh kz\Big] ,
\end{equation*}
so that

\begin{equation*}
f''(h)+k^{2}f(h)=
\frac{2a}{h\cosh kh}\Big[\cosh^{2}kh+k^{2}h^{2}\Big] .
\end{equation*}
The imposed basal shear

\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''(h)+k^{2}f(h)\big]=S_{0}\sin kx
\end{equation*}
gives

\begin{equation*}
a=\frac{S_{0}h\cosh kh}
        {2\mu\Big[\cosh^{2}kh+k^{2}h^{2}\Big]}\; .
\tag{3}
\end{equation*}
From (1)–(3)

\begin{equation*}
\rho g e_{s}= \frac{\mu}{k}f'''(0)
           =2\mu k a
           =\frac{S_{0}kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}} ,
\end{equation*}
i.e. with the conventional buoyancy restoring stress
$\sigma_{zz}=\Delta\rho g e\cos kx$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
       \chi(kh),\qquad 
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1},
\end{equation*}
the sign being the $\sin kx\leftrightarrow\cos kx$ $90^{\circ}$
phase shift.  The viscosity drops out of the steady state.  In
particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that in the lubrication, long-wave limit

\begin{equation*}
e_{s}\simeq \frac{kh\,S_{0}}{\Delta\rho g},\qquad 
\chi_{0}\simeq kh,
\end{equation*}
and $ \chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$.  For $kh\gg1$,
$\chi\sim2kh\,e^{-kh}\to0$.  Writing the normal stress balance with
the plate density $\rho$ this is $e_{s}= \chi S_{0}/\rho g$ with the
same $\chi$.  Up to the trivial $\rho/\Delta\rho$ replacement this is
the viscosity independent $e_{s}= \chi S_{0}/\Delta\rho g$ dynamic
topography.  The forms
$\chi\propto kh\sinh kh/[\sinh kh\cosh kh-kh]$ etc.  are obtained if
an extra impermeability condition $u_{z}(h)=0$, i.e. $f(h)=0$, is imposed
at the base.  With the stated free normal stress $\sigma_{zz}(h)=0$
and imposed shear $\sigma_{xz}(h)=S_{0}$ the base is free to move
vertically and the transfer function above is the correct steady
response.  The minus sign is the usual $90^{\circ}$ phase between the
$\sin kx$ shear and the $\cos kx$ topography. ∎

9.text:
With the stream function $\psi(x,z)=f(z)\sin kx$

\begin{equation*}
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx,\qquad 
\nabla^{4}\psi=0,
\end{equation*}
\begin{equation*}
f^{iv}-2k^{2}f''+k^{4}f=0,\qquad 
f(z)=(a+bz)\cosh kz+(c+dz)\sinh kz .
\end{equation*}
On the free top $z=0$
\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=0\;\;{\rm in\;the\;steady\;state},
\end{equation*}
i.e. $f(0)=f'(0)=0$, so that with $a=0$

\begin{equation*}
f(z)=bz\cosh kz+\Big[dz-\frac{b}{k}\Big]\sinh kz ,\qquad
f'(z)=d\sinh kz+kz\big[b\sinh kz+d\cosh kz\big] .
\end{equation*}
The pressure is

\begin{equation*}
p=-\frac{\mu}{k}\big[f'''-k^{2}f'\big]\cos kx ,
\end{equation*}
so that

\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx ,\qquad 
\sigma_{zz}= \frac{\mu}{k}\big[f'''-3k^{2}f'\big]\cos kx .
\end{equation*}
With $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
          =\frac{2\mu k^{2}b}{k}\cos kx
          =\Delta\rho g\,e\cos kx ,
\end{equation*}
hence in the steady state

\begin{equation*}
b=\frac{\Delta\rho g\,e}{2\mu k},\qquad 
f'''(0)=2k^{2}b=\frac{k\Delta\rho g}{\mu}\,e .
\end{equation*}
On the base $z=h$

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad 
\sigma_{xz}(h)=S_{0}\sin kx\iff 
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0} .
\end{equation*}
From $f'''(h)=3k^{2}f'(h)$

\begin{equation*}
b\big[\cosh kh-kh\sinh kh\big]=kh\,d\cosh kh ,
\end{equation*}
i.e.
\begin{equation*}
d=b\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh}\; .
\end{equation*}
With the form above

\begin{equation*}
f''+k^{2}f=2kd\cosh kz+2k^{2}z\big[b\cosh kz+d\sinh kz\big],
\end{equation*}
so that at $z=h$

\begin{equation*}
\big[f''+k^{2}f\big]_{h}
      =\frac{2b}{h\cosh kh}\Big[k^{2}h^{2}+\cosh^{2}kh\Big] .
\end{equation*}
Hence

\begin{equation*}
S_{0}=\mu\big[f''+k^{2}f\big]_{h}
     =\frac{2\mu b}{h\cosh kh}\Big[k^{2}h^{2}+\cosh^{2}kh\Big] .
\end{equation*}
Eliminating $b$ with $b=\Delta\rho g e/2\mu k$,

\begin{equation*}
\Delta\rho g e
   =S_{0}\,\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\end{equation*}
i.e.  up to the $90^{\circ}$ $\sin\leftrightarrow\cos$ sign

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
       \frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\qquad 
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1},
\end{equation*}
and the viscosity cancels in the steady state.  With the sign
convention $e>0$ upward the steady topography is in anti-phase with
the imposed shear, $e_{s}=-\chi S_{0}/\Delta\rho g$.

In particular
\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that the familiar long–wave, viscosity independent dynamic
topography is

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi_{0}=kh,
\end{equation*}
and with the hyperbolic factor retained $\chi(1)=\cosh1/(1+\cosh^{2}1)
\approx0.46$, $\chi\sim0.4\!-\!0.6$ for the geologically relevant
$kh\sim O(1)$.  With the density $\rho$ used in the statement
$\Delta\rho\to\rho$ this is $e_{s}= \chi S_{0}/\rho g$ with the $\chi$
above, often quoted as the $O(kh)$ viscous plate response.  The minus
sign is the usual $\sin kx\to\cos kx$ phase shift. ∎

6.text:
In the $k$ mode

\begin{equation*}
\psi=f(z)\sin kx\;,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx ,\qquad 
\nabla^{4}\psi=0,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\!\left[f''+k^{2}f\right]\sin kx,\qquad 
p=-\frac{\mu}{k}\!\left[f'''-k^{2}f'\right]\cos kx ,
\end{equation*}
\begin{equation*}
\sigma_{zz}=\mu\!\left[\frac{f'''}{k}-3kf'\right]\cos kx .
\end{equation*}
On the free top $u_{x}(0)=0$, $f'(0)=0$ and with the steady
kinematic condition $u_{z}(0)=0$, $f(0)=0$.  Then
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\rho ge_{s}\cos kx,
\qquad f_{0}'''(0)=\frac{k\rho g}{\mu}e_{s}.
\end{equation*}
With $f(0)=f'(0)=0$
\begin{equation*}
f(z)=C\Big[\sinh kz-kz\cosh kz\Big]+Dz\sinh kz,
\qquad B=-kC,
\end{equation*}
\begin{equation*}
f'''(0)=-2k^{3}C,\qquad 
C=-\frac{\rho ge_{s}}{2\mu k^{2}},\qquad f'(0)=0 .
\end{equation*}
The traction free base $\sigma_{zz}(h)=0$ is
$f'''(h)=3k^{2}f'(h)$, i.e.
\begin{equation*}
C\!\left[kh\sinh kh-\cosh kh\right]=Dh\cosh kh ,
\end{equation*}
\begin{equation*}
D=C\,\frac{kh\sinh kh-\cosh kh}{h\cosh kh}.
\end{equation*}
The imposed basal shear 
$\sigma_{xz}(h)=S_{0}\sin kx$ is
\begin{equation*}
\mu\!\left[f''(h)+k^{2}f(h)\right]=S_{0} .
\end{equation*}
With the $f$ above
\begin{equation*}
f''(h)+k^{2}f(h)
=2k\Big[D\cosh kh+Dkh\sinh kh-k^{2}hC\cosh kh\Big] ,
\end{equation*}
and with the $D$ above
\begin{equation*}
f''(h)+k^{2}f(h)=-\frac{2kC}{h\cosh kh}
\Big[\cosh^{2}kh+k^{2}h^{2}\Big] .
\end{equation*}
Hence
\begin{equation*}
-\,\frac{2\mu kC}{h\cosh kh}
\Big[\cosh^{2}kh+k^{2}h^{2}\Big]=S_{0},
\end{equation*}
and with $C=-\rho ge_{s}/2\mu k^{2}$
\begin{equation*}
\frac{\rho ge_{s}}{k}\,\frac{\cosh^{2}kh+k^{2}h^{2}}{h\cosh kh}=S_{0},
\end{equation*}
i.e. with the buoyancy stress $\Delta\rho g$,
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\,\cosh kh}{\cosh^{2}kh+k^{2}h^{2}} ,
\end{equation*}
the sign being the $90^{\circ}$ $\sin\leftrightarrow\cos$ phase
$e_{s}\propto-\sin kx$.  In the usual notation
$e_{s}=\chi S_{0}/\Delta\rho g$

\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1},
\end{equation*}
which is viscosity independent.  In particular

\[
\chi(kh)=\frac{kh}{ \cosh kh+ k^{2}h^{2}{\rm sech}kh},
\qquad 
\chi(kh)=kh\Big[\,1+O(k^{2}h^{2})\Big],\;kh\ll1,
\]

so that in the long wave lubrication limit

\[
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi_{0}\simeq kh,
\]

the familiar $e_{s}\propto kh\,S_{0}/\Delta\rho g$ viscous dynamic
topography.  For $kh=O(1)$ e.g. $kh=1$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$, i.e. 
$|e_{s}|\approx0.46\,S_{0}/\Delta\rho g$, the $O(1/2)$ viscous plate
factor quoted in the literature.  Up to the inessential
$\sin/\cos$ sign this is the steady, viscosity independent response
to the harmonic basal traction $S_{0}\sin kx$.  With the conventional
identification $\rho\to\Delta\rho$ the $\rho$ form is
$e_{s}= \chi S_{0}/\rho g$ with the $\chi$ above.  The $u_{z}(h)=0$
impermeable base gives the often quoted $\,\chi_{\rm imp}=
kh\sinh kh/[\sinh kh\cosh kh-kh]$ form. ∎

public_text.12:
With the stream function $\psi (x,z)=F(z)\sin kx$

\begin{equation*}
u_{x}=F'\sin kx ,\qquad u_{z}=-kF\cos kx ,\qquad 
\nabla^{4}\psi=0,
\end{equation*}

\begin{equation*}
F(z)=\big(a_{0}+a_{1}z\big)\cosh kz+\big(b_{0}+b_{1}z\big)\sinh kz,
\end{equation*}

and

\begin{equation*}
\sigma_{xz}= \mu\big[F''+k^{2}F\big]\sin kx ,
\qquad 
\sigma_{zz}= \mu k^{-1}\!\left[F'''-3k^{2}F'\right]\cos kx .
\end{equation*}

On the free rigid lid $z=0$

\begin{equation*}
u_{x}(0)=0\iff F'(0)=0,\qquad 
u_{z}(0)=\dot e\cos kx ,
\end{equation*}
so that in the steady state $\dot e=0$ 

\begin{equation*}
F(0)=0,\qquad F'(0)=0 .
\end{equation*}

Hence $a_{0}=0$ and $a_{1}=-k b_{0}$ and

\begin{equation*}
F(z)=b_{0}\Big[-k z\cosh kz+\sinh kz\Big]
     +\big(b_{1}z\cosh kz+b_{1}z\sinh kz\big) .
\end{equation*}

Free surface normal stress

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}F'''(0)\cos kx =\rho g e\cos kx ,
\end{equation*}

and $F'''(0)=-2k^{3}b_{0}$ gives

\begin{equation*}
b_{0}=-\frac{\rho g e}{2\mu k^{2}},\qquad 
a_{1}= \frac{\rho g e}{2\mu k},
\end{equation*}

so that the top normal stress is viscosity independent.  

The stress free base $\sigma_{zz}(h)=0$ is

\begin{equation*}
F'''(h)=3k^{2}F'(h) ,
\end{equation*}

i.e.

\begin{equation*}
b_{1}=b_{0}\Big[\,k\tanh kh-\frac1{h}\Big] ,
\end{equation*}

and the imposed basal shear

\begin{equation*}
\sigma_{xz}(h)=S_{0}\sin kx
\end{equation*}

is

\begin{equation*}
\mu\big[F''+k^{2}F\big]_{h}=S_{0}.
\end{equation*}

With $C=\cosh kh$, $S=\sinh kh$

\begin{equation*}
F''+k^{2}F\big|_{h}=2k\Big[b_{1}C+kh\big(-k b_{0}C+b_{1}S\big)\Big],
\end{equation*}

so that with the $b_{1}$ above

\begin{equation*}
2k\mu b_{0}\frac{k^{2}h^{2}+C^{2}}{kh C}= -S_{0}.
\end{equation*}

Eliminating $b_{0}$ with $b_{0}=-\rho g e/2\mu k^{2}$ gives the
viscosity independent steady balance

\begin{equation*}
\rho g e\,\frac{C^{2}+k^{2}h^{2}}{khC}=S_{0},
\end{equation*}

i.e. with the buoyancy restoring stress $\Delta\rho g e$,
$\rho\to\Delta\rho$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
       \frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
     \equiv \chi(kh)\frac{S_{0}}{\Delta\rho g} ,
\end{equation*}

\begin{equation*}
\;\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
        =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}\;
\end{equation*}

up to the $90^{\circ}$ $\sin kx\leftrightarrow\cos kx$ phase shift,
$e_{s}\propto -\,\chi S_{0}/\Delta\rho g$ with the sign convention
used above.  In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad 
\chi\simeq kh\;\;{\rm for}\;kh\ll1,
\end{equation*}

and $\chi\sim2kh\,e^{-kh}$ for $kh\gg1$.  For $kh=1$,
$\chi\approx0.46$, the familiar $O(kh)$ viscous dynamic topography
$e_{s}\approx kh\,S_{0}/\Delta\rho g$.  The $kh\sinh kh/[\sinh kh
\cosh kh-kh]$ forms obtained by Colleagues 3, 11, 14 follow from the
additional impermeable condition $F(h)=0$, i.e. $u_{z}(h)=0$, which is
not imposed by the statement $\sigma_{zz}(h)=0$.  With the stress free
base as stated the cosh numerator form above is the correct steady,
viscosity independent amplitude, often quoted in the long wave limit
as $e_{s}\approx kh\,S_{0}/\Delta\rho g$.  The minus sign is the
conventional $90^{\circ}$ phase between the $\sin kx$ basal shear and
the $\cos kx$ topography. ∎

public_text.5:
In the harmonic $ \sin kx\; \cos kx$ sector write with $a=k$
$\psi =F(z)\sin kx$, $u_{x}=F'\sin kx$, $u_{z}=-aF\cos kx$,
$\nabla^{4}\psi=0$,

\begin{equation*}
F^{(iv)}-2a^{2}F''+a^{4}F=0 ,\qquad 
F(z)=(p_{0}+p_{1}z)\cosh az+(q_{0}+q_{1}z)\sinh az ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\big[F''+a^{2}F\big]\sin kx,\qquad
\sigma_{zz}= \mu\Big[a^{-1}F'''-3aF'\Big]\cos kx .
\end{equation*}
On the free top $u_{x}(0)=0$ gives $F'(0)=0$ and in the steady state
$\dot e=u_{z}(0)=0$ gives $F(0)=0$.  Up to the $\sin\leftrightarrow\cos$
phase we may put

\begin{equation*}
F(0)=F'(0)=0,\qquad 
F(z)=C_{1}\sinh az+C_{3}z\sinh az-aC_{1}z\cosh az ,
\end{equation*}
so that

\begin{align*}
F'+a^{2}&\;:\;F''+a^{2}F=2a\Big[C_{3}\cosh az+C_{3}az\sinh az
        -a^{2}C_{1}z\cosh az\Big],\\
F'''&=3C_{3}a^{2}\sinh az+C_{3}a^{3}z\cosh az
      -2a^{3}C_{1}\cosh az-a^{4}C_{1}z\sinh az .
\end{align*}
Hence

\begin{equation*}
\sigma_{zz}(0)=\mu a^{-1}F'''(0)\cos kx
              =-2\mu a^{2}C_{1}\cos kx ,\qquad 
\rho g e_{s}=-2\mu a^{2}C_{1},
\end{equation*}
and the traction free base $\sigma_{zz}(h)=0$ is $F'''(h)=3a^{2}F'(h)$,
i.e.

\begin{equation*}
C_{1}=C_{3}h\cosh ah\Big/[ah\sinh ah-\cosh ah\Big] .
\end{equation*}
The imposed basal shear $\sigma_{xz}(h)=S_{0}\sin kx$ is

\begin{equation*}
\mu\big[F''(h)+a^{2}F(h)\big]=S_{0},
\end{equation*}
i.e.

\begin{equation*}
2a\Big[C_{3}\cosh ah+C_{3}ah\sinh ah-a^{2}C_{1}h\cosh ah\Big]
      =\frac{S_{0}}{\mu}\; .
\end{equation*}
Eliminating $C_{1}$,

\begin{equation*}
C_{3}= -\,\frac{S_{0}\big[ah\sinh ah-\cosh ah\big]}
             {2\mu a\big[\cosh^{2}ah+a^{2}h^{2}\big]},\qquad
C_{1}= -\,\frac{S_{0}h\cosh ah}
             {2\mu a\big[\cosh^{2}ah+a^{2}h^{2}\big]} ,
\end{equation*}
and with the free surface balance $\sigma_{zz}(0)=\rho g e_{s}\cos kx$

\begin{equation*}
\rho g e_{s}= -2\mu a^{2}C_{1}
           =\frac{S_{0}\,ah\cosh ah}{\cosh^{2}ah+a^{2}h^{2}} .
\end{equation*}
With the isostatic restoring stress $\Delta\rho g$,
$\rho\to\Delta\rho$,

\begin{equation*}
e_{s}= \chi(a h)\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(a h)=\frac{ah\cosh ah}{\cosh^{2}ah+a^{2}h^{2}}
        =\Big[\frac{ah}{\cosh ah}+\frac{\cosh ah}{ah}\Big]^{-1},
\end{equation*}
the sign being the $90^{\circ}$ $\sin kx\leftrightarrow\cos kx$
phase shift.  The viscosity drops out of the steady state.  In the
long wave limit $m=ah\ll1$, $\cosh m=1+O(m^{2})$,

\begin{equation*}
\chi(m)=\frac{m}{1+m^{2}}+O(m^{3})\simeq m,
\qquad e_{s}\simeq \frac{kh}{\Delta\rho g}S_{0},
\end{equation*}
and for the geologically relevant $m=O(1)$, e.g. $m=1$,
$\chi(1)=\cosh1/[\,1+\cosh^{2}1\,]\approx0.46$.  This is the
viscosity–independent viscous dynamic topography of a Stokes layer
with $u_{x}(0)=0$, $\sigma_{zz}(0)=\Delta\rho g e\cos kx$ on the top
and $\sigma_{zz}(h)=0$, $\sigma_{xz}(h)=S_{0}\sin kx$ on the base.
The forms with a $\sinh$ numerator, $\chi\propto m\sinh m/
\big[\sinh m\cosh m-m\big]$, are obtained if an extra impermeable
condition $u_{z}(h)=0$, $F(h)=0$, is imposed at the base.  With the
boundary conditions stated the transfer function is the
$\,m\cosh m/[\cosh^{2}m+m^{2}]$ function above, essentially
$|e_{s}|\sim kh\,S_{0}/\Delta\rho g$ in the lubrication limit.  Up to
the conventional sign $e_{s}=-\chi S_{0}/\Delta\rho g$ the magnitude
is the expression quoted. ∎

public_text.7:
With the harmonic mode $\psi(x,z)=f(z)\sin kx$,
$u_x=f'\sin kx$, $u_z=-k f\cos kx$, $\nabla^{4}\psi =0$ and
\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx,\qquad
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
the rigid lid is $u_x(0)=0$, $f'(0)=0$, and in the steady state
$u_z(0)=0$, $f(0)=0$.  Hence, up to the conventional sign,
\begin{equation*}
f(z)=\big[Bz+ D z\big]\sinh kz+Bz\cosh kz ,
\qquad f(0)=f'(0)=0,
\end{equation*}
and with $C=-B/k$ the four constants can be written as
$f(z)=Bz\cosh kz+C\sinh kz+Dz\sinh kz$.
The normal stress free base is
$\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h)$,
i.e.
\begin{equation*}
Bh\sinh kh+C\cosh kh+Dh\cosh kh=0,
\end{equation*}
so that with $C=-B/k$
\begin{equation*}
D=B\Big[\frac{1}{kh}-\tanh kh\Big] ,
\end{equation*}
and the impermeable base in the steady state is $f(h)=0$.  The basal
shear is
\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0},
\end{equation*}
i.e.
\begin{equation*}
2\mu k\Big[Bh k\cosh kh+D\cosh kh+Dh k\sinh kh\Big]=S_{0}.
\end{equation*}
Eliminating $D$ gives
\begin{equation*}
B= -\frac{S_{0}h}{2\mu k}\,
\frac{\sinh kh}{\cosh^{2}kh+k^{2}h^{2}} .
\end{equation*}
On the free surface $f'(0)=0$ so that
$\sigma_{zz}(0)=\mu f'''(0)k^{-1}\cos kx$ and
$f'''(0)=2k^{2}B$.  Hence
\begin{equation*}
\rho g e_{s}\cos kx =\frac{\mu}{k}f'''(0)\cos kx
 =\frac{2\mu k B}{\,}\cos kx,
\end{equation*}
and with the buoyancy restoring stress $\Delta\rho g e$,
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{k h\,\sinh kh}{\cosh^{2}kh+k^{2}h^{2}} ,
\end{equation*}
i.e. in the notation $e_{s}=\chi S_{0}/\Delta\rho g$
\begin{equation*}
\chi(kh)=\frac{k h\,\sinh(kh)}{\cosh^{2}(kh)+(kh)^{2}} .
\end{equation*}
The viscosity cancels as it must for the steady Stokes problem.
For $kh\ll1$, $\sinh kh=kh+O[(kh)^{3}]$, $\cosh kh=1+O[(kh)^{2}]$, so
$\chi=kh\,[1+O[(kh)^{2}]]$, the familiar lubrication scaling
$e_{s}\simeq kh\,S_{0}/\Delta\rho g$ with the $90^{\circ}$ $\sin/\cos$
phase shift between the imposed basal shear and the topographic cosine.
This is the $t\to\infty$ viscous dynamic topography and coincides with
the form quoted by the stream-function evaluations that keep the
pressure continuity $P(z)=-(\mu/k)[f'''-k^{2}f']$ together with the
steady kinematic condition $f(0)=f(h)=0$.  Up to the conventional
sign the magnitude is the expression above; with $\rho\to\Delta\rho$
it is the usual $e_{s}= \chi S_{0}/\Delta\rho g$ law.

public_text.3:
With the stream function $\psi=f(z)\sin kx$

\begin{equation*}
u_{x}=f'\sin kx,\qquad u_{z}=-k f\cos kx,\qquad 
\nabla^{4}\psi=0 ,
\end{equation*}
so that with $D=d/dz$
$(D^{2}-k^{2})^{2}f=0$.
On the free top $u_{x}(0)=0$ and in the steady state
$\dot e=u_{z}(0)=0$ so that

\begin{equation*}
f(0)=0,\qquad f'(0)=0,
\end{equation*}
and with $p=P(z)\cos kx$

\begin{equation*}
P=-\frac{\mu}{k}\Big[f'''-k^{2}f'\Big],\qquad 
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx,
\end{equation*}
\begin{equation*}
\sigma_{zz}=\Big[\frac{\mu}{k}f'''-3\mu k f'\Big]\cos kx .
\end{equation*}
Hence on $z=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\rho g\,e(t)\cos kx,
\qquad f'(0)=0,
\end{equation*}
and on the free base $z=h$

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad 
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0} .
\end{equation*}
With $f(0)=f'(0)=0$

\begin{equation*}
f(z)=Bz\cosh kz+Dz\sinh kz-\frac{B}{k}\sinh kz ,
\end{equation*}
so that
\begin{equation*}
f'(z)=kBz\sinh kz+D\sinh kz+kDz\cosh kz,
\end{equation*}
and
\begin{equation*}
f'''(z)=2k^{2}B\cosh kz+k^{3}Bz\sinh kz
       +3k^{2}D\sinh kz+k^{3}Dz\cosh kz .
\end{equation*}
$f'''(h)=3k^{2}f'(h)$ gives

\begin{equation*}
B\big[\cosh kh-kh\sinh kh\big]=khD\cosh kh ,
\end{equation*}
and with $c_{h}=\cosh kh$, $s_{h}=\sinh kh$,

\begin{equation*}
f''+k^{2}f=2k\Big[kBh\cosh kz+D\cosh kz
           +kDh\sinh kz\Big],
\end{equation*}
so that the basal shear

\begin{equation*}
\mu\big[f''+k^{2}f\big]_{h}=S_{0}
\end{equation*}
becomes

\begin{equation*}
2\mu k\Big[kBh\,c_{h}+D c_{h}+kDh s_{h}\Big]=S_{0}.
\end{equation*}
Eliminating $D$,

\begin{equation*}
D=B\,\frac{c_{h}-kh\,s_{h}}{kh\,c_{h}},\qquad
B=\frac{S_{0}h\,c_{h}}{2\mu\big[k^{2}h^{2}+c_{h}^{2}\big]} .
\end{equation*}
Now

\begin{equation*}
f'''(0)=2k^{2}B,\qquad 
\frac{\mu}{k}f'''(0)=\rho g e_{s},
\end{equation*}
hence in the steady state

\begin{equation*}
\rho g e_{s}=2\mu kB
          =\frac{S_{0}kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\end{equation*}
i.e. with the isostatic buoyancy $\Delta\rho g$ the normal stress
balance $\sigma_{zz}(0)=\Delta\rho g e\cos kx$ gives

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}\equiv
\chi(kh)\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
up to the $ \sin kx\leftrightarrow\cos kx$ $90^{\circ}$ phase,
conventionally written with the opposite sign.  In closed form

\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
       =\Bigg[\frac{\cosh kh}{kh}+\frac{kh}{\cosh kh}\Bigg]^{-1},
\end{equation*}
the viscosity dropping out of the steady state.  In particular

\begin{equation*}
\chi(kh)=kh\Big[1+O(k^{2}h^{2})\Big],\qquad kh\ll1,
\end{equation*}
so that in the usual long-wave lubrication limit

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad 
|e_{s}|\approx \chi_{0}\frac{S_{0}}{\Delta\rho g},\;\;
\chi_{0}\approx kh,
\end{equation*}
and for $kh=O(1)$ e.g. $kh=1$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.45\!-\!0.5$.  With the sign
convention $e_{s}>0$ upward this is $e_{s}=-\chi S_{0}/\Delta\rho g$
because the topography is $90^{\circ}$ out of phase with the imposed
$\sin kx$ basal shear.  The $\rho\to\Delta\rho$ replacement gives the
quoted form $e_{s}=\chi S_{0}/\rho g$ with the $\chi$ above.  This is the
familiar $e_{s}\propto kh\,S_{0}/\Delta\rho g$ viscous dynamic topography
produced by a harmonic basal traction. ∎

public_text.8:
With the $k$-mode

\begin{equation*}
\psi (x,z)=f(z)\sin kx,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu \big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}=\mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
and $(D^{2}-k^{2})^{2}f=0$.  On the material free surface

\begin{equation*}
u_{x}(0)=0\iff f'(0)=0,\qquad 
u_{z}(0)=\dot e\cos kx\iff f(0)=-\dot e/k ,
\end{equation*}
so that in the steady state $f(0)=0,\;f'(0)=0$ and

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\rho g e\cos kx ,
\qquad f'''(0)=\frac{k\rho g}{\mu}e .
\tag{1}
\end{equation*}
Put

\begin{equation*}
f(z)=a z\cosh kz+\big(Dz-a/k\big)\sinh kz ,
\end{equation*}
so that $f(0)=f'(0)=0$.  Then

\begin{equation*}
f'''(0)=2a k^{2},\qquad 
f'(z)=\big(akz+D\big)\sinh kz+Dkz\cosh kz ,
\end{equation*}
and with $\sigma_{zz}(h)=0$

\begin{equation*}
f'''(h)=3k^{2}f'(h)\Longleftrightarrow 
a\cosh kh=k h\big(a\sinh kh+D\cosh kh\big) ,
\end{equation*}
i.e.

\begin{equation*}
D=a\Big[\frac{1}{kh}-\tanh kh\Big]
   =a\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh}\; .
\tag{2}
\end{equation*}
Now

\begin{equation*}
f''+k^{2}f=2k\Big[akz\cosh kz+D\cosh kz+Dkz\sinh kz\Big] ,
\end{equation*}
so that

\begin{equation*}
f''(h)+k^{2}f(h)=
\frac{2a}{h\cosh kh}\Big[\cosh^{2}kh+k^{2}h^{2}\Big] .
\end{equation*}
The imposed basal shear

\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''(h)+k^{2}f(h)\big]=S_{0}\sin kx
\end{equation*}
gives

\begin{equation*}
a=\frac{S_{0}h\cosh kh}
        {2\mu\Big[\cosh^{2}kh+k^{2}h^{2}\Big]}\; .
\tag{3}
\end{equation*}
From (1)–(3)

\begin{equation*}
\rho g e_{s}= \frac{\mu}{k}f'''(0)
           =2\mu k a
           =\frac{S_{0}kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}} ,
\end{equation*}
i.e. with the conventional buoyancy restoring stress
$\sigma_{zz}=\Delta\rho g e\cos kx$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
       \chi(kh),\qquad 
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1},
\end{equation*}
the sign being the $\sin kx\leftrightarrow\cos kx$ $90^{\circ}$
phase shift.  The viscosity drops out of the steady state.  In
particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that in the lubrication, long-wave limit

\begin{equation*}
e_{s}\simeq \frac{kh\,S_{0}}{\Delta\rho g},\qquad 
\chi_{0}\simeq kh,
\end{equation*}
and $ \chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$.  For $kh\gg1$,
$\chi\sim2kh\,e^{-kh}\to0$.  Writing the normal stress balance with
the plate density $\rho$ this is $e_{s}= \chi S_{0}/\rho g$ with the
same $\chi$.  Up to the trivial $\rho/\Delta\rho$ replacement this is
the viscosity independent $e_{s}= \chi S_{0}/\Delta\rho g$ dynamic
topography.  The forms
$\chi\propto kh\sinh kh/[\sinh kh\cosh kh-kh]$ etc.  are obtained if
an extra impermeability condition $u_{z}(h)=0$, i.e. $f(h)=0$, is imposed
at the base.  With the stated free normal stress $\sigma_{zz}(h)=0$
and imposed shear $\sigma_{xz}(h)=S_{0}$ the base is free to move
vertically and the transfer function above is the correct steady
response.  The minus sign is the usual $90^{\circ}$ phase between the
$\sin kx$ shear and the $\cos kx$ topography. ∎

public_text.9:
With the stream function $\psi(x,z)=f(z)\sin kx$

\begin{equation*}
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx,\qquad 
\nabla^{4}\psi=0,
\end{equation*}
\begin{equation*}
f^{iv}-2k^{2}f''+k^{4}f=0,\qquad 
f(z)=(a+bz)\cosh kz+(c+dz)\sinh kz .
\end{equation*}
On the free top $z=0$
\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=0\;\;{\rm in\;the\;steady\;state},
\end{equation*}
i.e. $f(0)=f'(0)=0$, so that with $a=0$

\begin{equation*}
f(z)=bz\cosh kz+\Big[dz-\frac{b}{k}\Big]\sinh kz ,\qquad
f'(z)=d\sinh kz+kz\big[b\sinh kz+d\cosh kz\big] .
\end{equation*}
The pressure is

\begin{equation*}
p=-\frac{\mu}{k}\big[f'''-k^{2}f'\big]\cos kx ,
\end{equation*}
so that

\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx ,\qquad 
\sigma_{zz}= \frac{\mu}{k}\big[f'''-3k^{2}f'\big]\cos kx .
\end{equation*}
With $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
          =\frac{2\mu k^{2}b}{k}\cos kx
          =\Delta\rho g\,e\cos kx ,
\end{equation*}
hence in the steady state

\begin{equation*}
b=\frac{\Delta\rho g\,e}{2\mu k},\qquad 
f'''(0)=2k^{2}b=\frac{k\Delta\rho g}{\mu}\,e .
\end{equation*}
On the base $z=h$

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad 
\sigma_{xz}(h)=S_{0}\sin kx\iff 
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0} .
\end{equation*}
From $f'''(h)=3k^{2}f'(h)$

\begin{equation*}
b\big[\cosh kh-kh\sinh kh\big]=kh\,d\cosh kh ,
\end{equation*}
i.e.
\begin{equation*}
d=b\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh}\; .
\end{equation*}
With the form above

\begin{equation*}
f''+k^{2}f=2kd\cosh kz+2k^{2}z\big[b\cosh kz+d\sinh kz\big],
\end{equation*}
so that at $z=h$

\begin{equation*}
\big[f''+k^{2}f\big]_{h}
      =\frac{2b}{h\cosh kh}\Big[k^{2}h^{2}+\cosh^{2}kh\Big] .
\end{equation*}
Hence

\begin{equation*}
S_{0}=\mu\big[f''+k^{2}f\big]_{h}
     =\frac{2\mu b}{h\cosh kh}\Big[k^{2}h^{2}+\cosh^{2}kh\Big] .
\end{equation*}
Eliminating $b$ with $b=\Delta\rho g e/2\mu k$,

\begin{equation*}
\Delta\rho g e
   =S_{0}\,\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\end{equation*}
i.e.  up to the $90^{\circ}$ $\sin\leftrightarrow\cos$ sign

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
       \frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\qquad 
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1},
\end{equation*}
and the viscosity cancels in the steady state.  With the sign
convention $e>0$ upward the steady topography is in anti-phase with
the imposed shear, $e_{s}=-\chi S_{0}/\Delta\rho g$.

In particular
\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that the familiar long–wave, viscosity independent dynamic
topography is

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi_{0}=kh,
\end{equation*}
and with the hyperbolic factor retained $\chi(1)=\cosh1/(1+\cosh^{2}1)
\approx0.46$, $\chi\sim0.4\!-\!0.6$ for the geologically relevant
$kh\sim O(1)$.  With the density $\rho$ used in the statement
$\Delta\rho\to\rho$ this is $e_{s}= \chi S_{0}/\rho g$ with the $\chi$
above, often quoted as the $O(kh)$ viscous plate response.  The minus
sign is the usual $\sin kx\to\cos kx$ phase shift. ∎

public_text.6:
In the $k$ mode

\begin{equation*}
\psi=f(z)\sin kx\;,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx ,\qquad 
\nabla^{4}\psi=0,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\!\left[f''+k^{2}f\right]\sin kx,\qquad 
p=-\frac{\mu}{k}\!\left[f'''-k^{2}f'\right]\cos kx ,
\end{equation*}
\begin{equation*}
\sigma_{zz}=\mu\!\left[\frac{f'''}{k}-3kf'\right]\cos kx .
\end{equation*}
On the free top $u_{x}(0)=0$, $f'(0)=0$ and with the steady
kinematic condition $u_{z}(0)=0$, $f(0)=0$.  Then
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\rho ge_{s}\cos kx,
\qquad f_{0}'''(0)=\frac{k\rho g}{\mu}e_{s}.
\end{equation*}
With $f(0)=f'(0)=0$
\begin{equation*}
f(z)=C\Big[\sinh kz-kz\cosh kz\Big]+Dz\sinh kz,
\qquad B=-kC,
\end{equation*}
\begin{equation*}
f'''(0)=-2k^{3}C,\qquad 
C=-\frac{\rho ge_{s}}{2\mu k^{2}},\qquad f'(0)=0 .
\end{equation*}
The traction free base $\sigma_{zz}(h)=0$ is
$f'''(h)=3k^{2}f'(h)$, i.e.
\begin{equation*}
C\!\left[kh\sinh kh-\cosh kh\right]=Dh\cosh kh ,
\end{equation*}
\begin{equation*}
D=C\,\frac{kh\sinh kh-\cosh kh}{h\cosh kh}.
\end{equation*}
The imposed basal shear 
$\sigma_{xz}(h)=S_{0}\sin kx$ is
\begin{equation*}
\mu\!\left[f''(h)+k^{2}f(h)\right]=S_{0} .
\end{equation*}
With the $f$ above
\begin{equation*}
f''(h)+k^{2}f(h)
=2k\Big[D\cosh kh+Dkh\sinh kh-k^{2}hC\cosh kh\Big] ,
\end{equation*}
and with the $D$ above
\begin{equation*}
f''(h)+k^{2}f(h)=-\frac{2kC}{h\cosh kh}
\Big[\cosh^{2}kh+k^{2}h^{2}\Big] .
\end{equation*}
Hence
\begin{equation*}
-\,\frac{2\mu kC}{h\cosh kh}
\Big[\cosh^{2}kh+k^{2}h^{2}\Big]=S_{0},
\end{equation*}
and with $C=-\rho ge_{s}/2\mu k^{2}$
\begin{equation*}
\frac{\rho ge_{s}}{k}\,\frac{\cosh^{2}kh+k^{2}h^{2}}{h\cosh kh}=S_{0},
\end{equation*}
i.e. with the buoyancy stress $\Delta\rho g$,
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\,\cosh kh}{\cosh^{2}kh+k^{2}h^{2}} ,
\end{equation*}
the sign being the $90^{\circ}$ $\sin\leftrightarrow\cos$ phase
$e_{s}\propto-\sin kx$.  In the usual notation
$e_{s}=\chi S_{0}/\Delta\rho g$

\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1},
\end{equation*}
which is viscosity independent.  In particular

\[
\chi(kh)=\frac{kh}{ \cosh kh+ k^{2}h^{2}{\rm sech}kh},
\qquad 
\chi(kh)=kh\Big[\,1+O(k^{2}h^{2})\Big],\;kh\ll1,
\]

so that in the long wave lubrication limit

\[
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi_{0}\simeq kh,
\]

the familiar $e_{s}\propto kh\,S_{0}/\Delta\rho g$ viscous dynamic
topography.  For $kh=O(1)$ e.g. $kh=1$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$, i.e. 
$|e_{s}|\approx0.46\,S_{0}/\Delta\rho g$, the $O(1/2)$ viscous plate
factor quoted in the literature.  Up to the inessential
$\sin/\cos$ sign this is the steady, viscosity independent response
to the harmonic basal traction $S_{0}\sin kx$.  With the conventional
identification $\rho\to\Delta\rho$ the $\rho$ form is
$e_{s}= \chi S_{0}/\rho g$ with the $\chi$ above.  The $u_{z}(h)=0$
impermeable base gives the often quoted $\,\chi_{\rm imp}=
kh\sinh kh/[\sinh kh\cosh kh-kh]$ form. ∎

9.text:
With the $k$–mode

$\psi(x,z)=f(z)\sin kx$,      $u_{x}=f'\sin kx$,   $u_{z}=-k f\cos kx$,
$\nabla^{4}\psi=0$, $(D^{2}-k^{2})^{2}f=0$,
\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}= \mu\Big[k^{-1}f'''-3k f'\Big]\cos kx ,
\end{equation*}
the rigid free top is $u_{x}(0)=0$, $f'(0)=0$ and in the steady state
$u_{z}(0)=\dot e=0$, $f(0)=0$.  With $f(0)=f'(0)=0$
\begin{equation*}
f(z)=Bz\cosh kz+\Big[D\,z-B/k\Big]\sinh kz ,
\end{equation*}
\begin{equation*}
f'''(0)=2k^{2}B,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\Delta\rho g\,e\cos kx ,
\end{equation*}
so that on the free surface
\begin{equation*}
\Delta\rho g\, e=2\mu k B ,\qquad 
B=\frac{\Delta\rho g\,e}{2\mu k} .
\tag{1}
\end{equation*}
On the base $z=h$
\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad 
\sigma_{xz}(h)=S_{0}\sin kx\iff \mu\big[f''(h)+k^{2}f(h)\big]=S_{0}.
\end{equation*}
$f'''(h)=3k^{2}f'(h)$ gives
\begin{equation*}
B\big[\cosh kh-kh\sinh kh\big]=kh\,D\cosh kh ,
\qquad 
D=B\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh},
\end{equation*}
and
\begin{equation*}
f''+k^{2}f=2k\Big[Bkh\cosh kz+D\cosh kz+Dkh\sinh kz\Big] .
\end{equation*}
Hence
\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
 =2\mu k\Big[Bkh\cosh kh+D\cosh kh+Dkh\sinh kh\Big]=S_{0},
\end{equation*}
i.e. on elimination of $D$
\begin{equation*}
2\mu k\,B\,
\frac{k^{2}h^{2}+\cosh^{2}kh}{h\cosh kh}=S_{0}.
\end{equation*}
With (1)
\begin{equation*}
 \Delta\rho g e_{s}
   = \frac{S_{0}\,kh\cosh kh}{\,k^{2}h^{2}+\cosh^{2}kh\,},
\end{equation*}
the viscosity cancelling in the steady Stokes balance.  In the
convention $e_{s}= \chi S_{0}/\Delta\rho g$ with the $\,90^{\circ}\,$
$\sin kx\leftrightarrow\cos kx$ phase,
\begin{equation*}
e_{s}= -\,\chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}>0 ,
\end{equation*}
the minus sign being the conventional anti-phase of the $\cos kx$
topography with the imposed $\sin kx$ basal shear.  Up to the
inessential sign
\begin{equation*}
|e_{s}|=\frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\end{equation*}
the viscosity independent steady viscous dynamic topography.  In
particular
\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that in the long wave, lubrication limit
\begin{equation*}
\chi_{0}\simeq kh,\qquad 
e_{s}\simeq \pm\,kh\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
and $\chi\to2kh\,e^{-kh}\to0$ for $kh\gg1$.  For the geologically
relevant $kh\sim O(1)$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$, $|\chi|\approx0.4\!-\!0.6$,
i.e. the familiar $e_{s}\approx kh\,S_{0}/\Delta\rho g$ response.  The
$\,kh\sinh kh/[\sinh kh\cosh kh-kh]$ forms are obtained if the extra
kinematic condition $u_{z}(h)=0$, $f(h)=0$, is imposed at the base; with
the stated data $\sigma_{zz}(h)=0$, $\sigma_{xz}(h)=S_{0}$ and no
impermeability condition the transfer function above is the correct
steady, viscosity independent response.  Replacing $\Delta\rho\to\rho$
gives the quoted $e_{s}= \chi S_{0}/\rho g$ form. ∎

11.text:
In the $k$-sector put $\psi(x,z)=f(z)\sin kx$,
$u_{x}=f^{\prime}\sin kx$, $u_{z}=-kf\cos kx$ and
$(D^{2}-k^{2})^{2}f=0$.
With the rigid lid

\begin{equation*}
u_{x}(0)=0\iff f^{\prime}(0)=0 ,\qquad 
\dot e=u_{z}(0)=-kf(0)\cos kx ,
\end{equation*}
so that in the steady state $f(0)=f^{\prime}(0)=0$ and

\begin{equation*}
\sigma_{xz}= \mu\big[f^{\prime\prime}+k^{2}f\big]\sin kx,\qquad
\sigma_{zz}= \mu\Big[k^{-1}f^{\prime\prime\prime}-3k f^{\prime}\Big]\cos kx .
\end{equation*}
On the free surface

\begin{equation*}
\sigma_{zz}(0)=\mu k^{-1}f^{\prime\prime\prime}(0)\cos kx
           =\Delta\rho g\,e\cos kx ,
\end{equation*}
i.e. with $f(0)=f^{\prime}(0)=0$

\begin{equation*}
f(z)=A\big[\sinh kz-kz\cosh kz\big]+Bz\sinh kz ,
\end{equation*}
$f^{\prime\prime\prime}(0)=2k^{2}A$ and
\begin{equation*}
\Delta\rho g\,e=2\mu kA .
\tag{1}
\end{equation*}
The stress free base is

\begin{equation*}
\sigma_{zz}(h)=0\iff f^{\prime\prime\prime}(h)=3k^{2}f^{\prime}(h),
\qquad 
\mu\big[f^{\prime\prime}(h)+k^{2}f(h)\big]=S_{0} ,
\end{equation*}
i.e.

\begin{equation*}
A\big[\cosh kh-kh\sinh kh\big]=Bkh\cosh kh .
\tag{2}
\end{equation*}
Now
\begin{equation*}
f^{\prime\prime}+k^{2}f=2k\Big[Akh\cosh kz+B\cosh kz+Bkh\sinh kz\Big],
\end{equation*}
so that with (2)

\begin{equation*}
\mu\big[f^{\prime\prime}(h)+k^{2}f(h)\big]
=2\mu kA\,
\frac{k^{2}h^{2}+\cosh^{2}kh}{h\cosh kh}=S_{0}.
\tag{3}
\end{equation*}
Eliminating $A$ between (1) and (3),

\begin{equation*}
\Delta\rho g e_{s}
      =S_{0}\,
        \frac{kh\cosh kh}{\,k^{2}h^{2}+\cosh^{2}kh\,} ,
\end{equation*}
the viscosity cancelling in the steady Stokes balance.  With the
conventional upward positive sign the topography is $90^{\circ}$ out of
phase with the imposed $\sin kx$ shear, $e_{s}\propto-\cos kx$, so that
in magnitude

\begin{equation*}
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\left[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\right]^{-1}>0,
\end{equation*}
and with the sign convention used above
$e_{s}=-\chi S_{0}/\Delta\rho g$.
In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that in the lubrication long wave limit

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad 
|\chi_{0}|\simeq kh,
\end{equation*}
and $\chi\sim 2kh\,e^{-kh}\to0$ for $kh\gg1$.  For $kh=1$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$, the familiar $0.3\!-\!0.6\,kh$
viscous dynamic topography.  The $kh\sinh kh/[\cosh^{2}kh+k^{2}h^{2}]$
forms quoted by Colleagues 7,13,14 are obtained if the additional
kinematic condition $u_{z}(h)=0$, $f(h)=0$, i.e. an impermeable base,
is imposed.  With the stated data $\sigma_{zz}(h)=0$ the base is free to
move vertically and the $kh\cosh kh/[\cosh^{2}kh+k^{2}h^{2}]$ transfer
function above is the viscosity independent steady response, often
quoted in the thin plate limit as $e_{s}\approx kh\,S_{0}/\Delta\rho g$.
Up to the inessential $\sin\leftrightarrow\cos$ sign this is the
$O(kh)$ viscous plate response. ∎

6.text:
With the $k$-mode

\begin{equation*}
\psi(x,z)=f(z)\sin kx,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-k f\cos kx ,
\end{equation*}
$(D^{2}-k^{2})^{2}f=0$ and for a constant $\mu$

\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx ,\qquad 
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
the hydrostatic part being removed.  On the rigid lid

\begin{equation*}
u_{x}(0)=0\iff f'(0)=0 ,\qquad 
u_{z}(0)=\dot e\cos kx ,
\end{equation*}
so that in the steady state $\dot e=0$

\begin{equation*}
f(0)=f'(0)=0 ,
\end{equation*}
and with $f(0)=f'(0)=0$

\begin{equation*}
f(z)=C\big[\sinh kz-kz\cosh kz\big]+Dz \sinh kz ,
\end{equation*}
\begin{equation*}
f'(0)=0,\qquad f'''(0)=-2k^{3}C .
\end{equation*}
Hence

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)
          =-2\mu k^{2}C=\rho g e\cos kx ,
\end{equation*}
i.e. with the buoyancy restoring stress written as $\Delta\rho g e$

\begin{equation*}
\Delta\rho g e_{s}=-2\mu k^{2}C ,\qquad 
e_{s}\propto\cos kx ,
\end{equation*}
the steady topography being $90^{\circ}$ out of phase with the
imposed $\sin kx$ basal traction.  On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h), \qquad 
\sigma_{xz}(h)=S_{0}\sin kx ,
\end{equation*}
i.e.

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0},\qquad 
f'''(h)=3k^{2}f'(h) .
\end{equation*}
With the above $f$

\begin{equation*}
f'(z)=-k^{2}Cz\sinh kz+D\sinh kz+ Dkz\cosh kz ,
\end{equation*}
\begin{equation*}
f'''(z)=-2k^{3}C\cosh kz-k^{4}Cz\sinh kz
       +3k^{2}D\sinh kz+k^{3}Dz\cosh kz .
\end{equation*}
$f'''(h)=3k^{2}f'(h)$ gives

\begin{equation*}
C\big[kh\sinh kh-\cosh kh\big]=Dh\cosh kh ,\qquad
D=C\,\frac{kh\sinh kh-\cosh kh}{h\cosh kh},
\end{equation*}
and

\begin{equation*}
f''+k^{2}f=2k\Big[ D\cosh kz+Dkz\sinh kz-
k^{2}Cz\cosh kz\Big] .
\end{equation*}
Hence

\begin{equation*}
\Big[f''+k^{2}f\Big]_{h}
   =-\,\frac{2kC}{h\cosh kh}\Big[k^{2}h^{2}+\cosh^{2}kh\Big],
\end{equation*}
so that

\begin{equation*}
S_{0}
   =\mu\Big[f''+k^{2}f\Big]_{h}
   =-\frac{2\mu kC}{h\cosh kh}\Big[k^{2}h^{2}+\cosh^{2}kh\Big],
\end{equation*}
\begin{equation*}
C=-\frac{S_{0}h\cosh kh}
        {2\mu k\big[k^{2}h^{2}+\cosh^{2}kh\big]}\; .
\end{equation*}
Using $\Delta\rho g e_{s}=-2\mu k^{2}C$ the viscosity cancels in the
steady Stokes balance and

\begin{equation*}
\Delta\rho g e_{s}
   =\frac{S_{0}kh\cosh kh}
          {k^{2}h^{2}+\cosh^{2}kh} ,
\end{equation*}
i.e. up to the conventional $\sin kx\leftrightarrow\cos kx$ sign

\begin{equation*}
e_{s}(x)=\chi(kh)\,\frac{S_{0}}{\Delta\rho g}\cos kx ,\qquad
e_{s}=-\chi\frac{S_{0}}{\Delta\rho g}
\end{equation*}
with the magnitude transfer function

\begin{equation*}
\;\chi(kh)=\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
        =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}>0\;,
\end{equation*}
which is viscosity independent.  In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that on the long wave lubrication scale

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad 
|\chi_{0}|\simeq kh ,
\end{equation*}
the well known $O(kh)$ viscous dynamic topography, $e_{s}\propto-
\cos kx$ for a $+ \sin kx$ basal shear.  For $kh=O(1)$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$ and
$\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  With the usual
$\rho\to\Delta\rho$ identification this is the quoted
$e_{s}=\chi S_{0}/\rho g$ steady amplitude, the minus sign being the
$90^{\circ}$ phase shift between the imposed basal shear and the
$\cos kx$ topography.  With the magnitude convention the thin-plate
limit is $|\chi_{0}|\approx kh$, i.e. $e_{s}\approx kh\,S_{0}/
\Delta\rho g$, the usual $O(kh)$ viscous plate response. ∎

12.text:
With the normal mode
$\psi(x,z)=f(z)\sin kx$,
$u_{x}=f'\sin kx$ , $u_{z}=-kf\cos kx$,
$(D^{2}-k^{2})^{2}f=0$,
\begin{equation*}
\sigma_{xz}= \mu\!\left[f''+k^{2}f\right]\sin kx ,\qquad
\sigma_{zz}= \mu\!\left[\frac{f'''}{k}-3k f'\right]\cos kx .
\end{equation*}
On the rigid lid $u_{x}(0)=0$, $f'(0)=0$ and in the steady state
$u_{z}(0)=0$, $f(0)=0$.  With $f(0)=f'(0)=0$
\begin{equation*}
f(z)=a_{1}z\cosh kz+\Big[b_{1}z-\frac{a_{1}}{k}\Big]\sinh kz ,
\qquad
f'''(0)=2k^{2}a_{1}\;,
\end{equation*}
so that  
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
               =2\mu k a_{1}\cos kx =\Delta\rho g\,e\cos kx ,
\qquad 
a_{1}=\frac{\Delta\rho g\,e}{2\mu k}\;,
\end{equation*}
and, up to the inessential $\sin\leftrightarrow\cos$ phase, 
$e(t)=-2\mu k^{2}C_{1}/\Delta\rho g$ with the usual
$C_{1}$ notation.  The traction free base is
\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad
\sigma_{xz}(h)=S_{0}\sin kx\iff \mu\big[f''+k^{2}f\big]_{h}=S_{0} .
\end{equation*}
With $C_{h}=\cosh kh$, $S_{h}=\sinh kh$ the $\sigma_{zz}(h)=0$
condition gives
\begin{equation*}
a_{1}C_{h}=kh\Big[a_{1}S_{h}+b_{1}C_{h}\Big],\qquad
b_{1}=a_{1}\frac{C_{h}-khS_{h}}{khC_{h}} .
\end{equation*}
Moreover
\begin{equation*}
f''+k^{2}f=2k\Big[b_{1}\cosh kz+kz\big(a_{1}\cosh kz
       +b_{1}\sinh kz\big)\Big],
\end{equation*}
so that at $z=h$
\begin{equation*}
\big[f''+k^{2}f\big]_{h}
   =\frac{2a_{1}}{hC_{h}}\Big[C_{h}^{2}+k^{2}h^{2}\Big] .
\end{equation*}
Hence
\begin{equation*}
S_{0}= \mu\big[f''+k^{2}f\big]_{h}
     =\frac{2\mu a_{1}}{hC_{h}}\Big[C_{h}^{2}+k^{2}h^{2}\Big]
\end{equation*}
and with $a_{1}=\Delta\rho g e_{s}/2\mu k$
\begin{equation*}
\Delta\rho g\,e_{s}
   =S_{0}\,\frac{khC_{h}}{C_{h}^{2}+k^{2}h^{2}}\;,
\end{equation*}
i.e. with the conventional sign $e_{s}\propto-\cos kx$
\begin{equation*}
e_{s}= -\,\chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}>0,
\end{equation*}
the viscosity cancelling in the steady state.  The $90^{\circ}$
$\sin kx\leftrightarrow\cos kx$ phase is the usual anti–phase
between the imposed basal shear $S_{0}\sin kx$ and the topographic
$\cos kx$ response.  In magnitude
\begin{equation*}
|e_{s}|=\chi(kh)\frac{S_{0}}{\Delta\rho g},
\end{equation*}
and
\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4})\simeq kh,
\qquad kh\ll1,
\end{equation*}
so that the familiar long–wave, lubrication limit is
\begin{equation*}
|e_{s}|\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi_{0}\simeq kh,
\end{equation*}
with $\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$ and
$\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  With the $\rho$ notation of
the statement $\Delta\rho\to\rho$ this is $e_{s}= \chi S_{0}/\rho g$
up to the conventional $-\,$sign.  The $kh\sinh kh/[\sinh kh\cosh
kh-kh]$ forms are obtained if the extra kinematic condition
$u_{z}(h)=0$, $f(h)=0$, i.e. an impermeable base, is imposed; with the
stated free normal stress $\sigma_{zz}(h)=0$ the base is free to move
vertically and the transfer function above is the steady, viscosity
independent viscous dynamic topography.  This is the $O(kh)$ result
normally quoted as $e_{s}\approx kh\,S_{0}/\Delta\rho g$. ∎

public_text.9:
With the $k$–mode

$\psi(x,z)=f(z)\sin kx$,      $u_{x}=f'\sin kx$,   $u_{z}=-k f\cos kx$,
$\nabla^{4}\psi=0$, $(D^{2}-k^{2})^{2}f=0$,
\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}= \mu\Big[k^{-1}f'''-3k f'\Big]\cos kx ,
\end{equation*}
the rigid free top is $u_{x}(0)=0$, $f'(0)=0$ and in the steady state
$u_{z}(0)=\dot e=0$, $f(0)=0$.  With $f(0)=f'(0)=0$
\begin{equation*}
f(z)=Bz\cosh kz+\Big[D\,z-B/k\Big]\sinh kz ,
\end{equation*}
\begin{equation*}
f'''(0)=2k^{2}B,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\Delta\rho g\,e\cos kx ,
\end{equation*}
so that on the free surface
\begin{equation*}
\Delta\rho g\, e=2\mu k B ,\qquad 
B=\frac{\Delta\rho g\,e}{2\mu k} .
\tag{1}
\end{equation*}
On the base $z=h$
\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad 
\sigma_{xz}(h)=S_{0}\sin kx\iff \mu\big[f''(h)+k^{2}f(h)\big]=S_{0}.
\end{equation*}
$f'''(h)=3k^{2}f'(h)$ gives
\begin{equation*}
B\big[\cosh kh-kh\sinh kh\big]=kh\,D\cosh kh ,
\qquad 
D=B\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh},
\end{equation*}
and
\begin{equation*}
f''+k^{2}f=2k\Big[Bkh\cosh kz+D\cosh kz+Dkh\sinh kz\Big] .
\end{equation*}
Hence
\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
 =2\mu k\Big[Bkh\cosh kh+D\cosh kh+Dkh\sinh kh\Big]=S_{0},
\end{equation*}
i.e. on elimination of $D$
\begin{equation*}
2\mu k\,B\,
\frac{k^{2}h^{2}+\cosh^{2}kh}{h\cosh kh}=S_{0}.
\end{equation*}
With (1)
\begin{equation*}
 \Delta\rho g e_{s}
   = \frac{S_{0}\,kh\cosh kh}{\,k^{2}h^{2}+\cosh^{2}kh\,},
\end{equation*}
the viscosity cancelling in the steady Stokes balance.  In the
convention $e_{s}= \chi S_{0}/\Delta\rho g$ with the $\,90^{\circ}\,$
$\sin kx\leftrightarrow\cos kx$ phase,
\begin{equation*}
e_{s}= -\,\chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}>0 ,
\end{equation*}
the minus sign being the conventional anti-phase of the $\cos kx$
topography with the imposed $\sin kx$ basal shear.  Up to the
inessential sign
\begin{equation*}
|e_{s}|=\frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\end{equation*}
the viscosity independent steady viscous dynamic topography.  In
particular
\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that in the long wave, lubrication limit
\begin{equation*}
\chi_{0}\simeq kh,\qquad 
e_{s}\simeq \pm\,kh\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
and $\chi\to2kh\,e^{-kh}\to0$ for $kh\gg1$.  For the geologically
relevant $kh\sim O(1)$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$, $|\chi|\approx0.4\!-\!0.6$,
i.e. the familiar $e_{s}\approx kh\,S_{0}/\Delta\rho g$ response.  The
$\,kh\sinh kh/[\sinh kh\cosh kh-kh]$ forms are obtained if the extra
kinematic condition $u_{z}(h)=0$, $f(h)=0$, is imposed at the base; with
the stated data $\sigma_{zz}(h)=0$, $\sigma_{xz}(h)=S_{0}$ and no
impermeability condition the transfer function above is the correct
steady, viscosity independent response.  Replacing $\Delta\rho\to\rho$
gives the quoted $e_{s}= \chi S_{0}/\rho g$ form. ∎

public_text.11:
In the $k$-sector put $\psi(x,z)=f(z)\sin kx$,
$u_{x}=f^{\prime}\sin kx$, $u_{z}=-kf\cos kx$ and
$(D^{2}-k^{2})^{2}f=0$.
With the rigid lid

\begin{equation*}
u_{x}(0)=0\iff f^{\prime}(0)=0 ,\qquad 
\dot e=u_{z}(0)=-kf(0)\cos kx ,
\end{equation*}
so that in the steady state $f(0)=f^{\prime}(0)=0$ and

\begin{equation*}
\sigma_{xz}= \mu\big[f^{\prime\prime}+k^{2}f\big]\sin kx,\qquad
\sigma_{zz}= \mu\Big[k^{-1}f^{\prime\prime\prime}-3k f^{\prime}\Big]\cos kx .
\end{equation*}
On the free surface

\begin{equation*}
\sigma_{zz}(0)=\mu k^{-1}f^{\prime\prime\prime}(0)\cos kx
           =\Delta\rho g\,e\cos kx ,
\end{equation*}
i.e. with $f(0)=f^{\prime}(0)=0$

\begin{equation*}
f(z)=A\big[\sinh kz-kz\cosh kz\big]+Bz\sinh kz ,
\end{equation*}
$f^{\prime\prime\prime}(0)=2k^{2}A$ and
\begin{equation*}
\Delta\rho g\,e=2\mu kA .
\tag{1}
\end{equation*}
The stress free base is

\begin{equation*}
\sigma_{zz}(h)=0\iff f^{\prime\prime\prime}(h)=3k^{2}f^{\prime}(h),
\qquad 
\mu\big[f^{\prime\prime}(h)+k^{2}f(h)\big]=S_{0} ,
\end{equation*}
i.e.

\begin{equation*}
A\big[\cosh kh-kh\sinh kh\big]=Bkh\cosh kh .
\tag{2}
\end{equation*}
Now
\begin{equation*}
f^{\prime\prime}+k^{2}f=2k\Big[Akh\cosh kz+B\cosh kz+Bkh\sinh kz\Big],
\end{equation*}
so that with (2)

\begin{equation*}
\mu\big[f^{\prime\prime}(h)+k^{2}f(h)\big]
=2\mu kA\,
\frac{k^{2}h^{2}+\cosh^{2}kh}{h\cosh kh}=S_{0}.
\tag{3}
\end{equation*}
Eliminating $A$ between (1) and (3),

\begin{equation*}
\Delta\rho g e_{s}
      =S_{0}\,
        \frac{kh\cosh kh}{\,k^{2}h^{2}+\cosh^{2}kh\,} ,
\end{equation*}
the viscosity cancelling in the steady Stokes balance.  With the
conventional upward positive sign the topography is $90^{\circ}$ out of
phase with the imposed $\sin kx$ shear, $e_{s}\propto-\cos kx$, so that
in magnitude

\begin{equation*}
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\left[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\right]^{-1}>0,
\end{equation*}
and with the sign convention used above
$e_{s}=-\chi S_{0}/\Delta\rho g$.
In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that in the lubrication long wave limit

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad 
|\chi_{0}|\simeq kh,
\end{equation*}
and $\chi\sim 2kh\,e^{-kh}\to0$ for $kh\gg1$.  For $kh=1$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$, the familiar $0.3\!-\!0.6\,kh$
viscous dynamic topography.  The $kh\sinh kh/[\cosh^{2}kh+k^{2}h^{2}]$
forms quoted by Colleagues 7,13,14 are obtained if the additional
kinematic condition $u_{z}(h)=0$, $f(h)=0$, i.e. an impermeable base,
is imposed.  With the stated data $\sigma_{zz}(h)=0$ the base is free to
move vertically and the $kh\cosh kh/[\cosh^{2}kh+k^{2}h^{2}]$ transfer
function above is the viscosity independent steady response, often
quoted in the thin plate limit as $e_{s}\approx kh\,S_{0}/\Delta\rho g$.
Up to the inessential $\sin\leftrightarrow\cos$ sign this is the
$O(kh)$ viscous plate response. ∎

public_text.6:
With the $k$-mode

\begin{equation*}
\psi(x,z)=f(z)\sin kx,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-k f\cos kx ,
\end{equation*}
$(D^{2}-k^{2})^{2}f=0$ and for a constant $\mu$

\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx ,\qquad 
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
the hydrostatic part being removed.  On the rigid lid

\begin{equation*}
u_{x}(0)=0\iff f'(0)=0 ,\qquad 
u_{z}(0)=\dot e\cos kx ,
\end{equation*}
so that in the steady state $\dot e=0$

\begin{equation*}
f(0)=f'(0)=0 ,
\end{equation*}
and with $f(0)=f'(0)=0$

\begin{equation*}
f(z)=C\big[\sinh kz-kz\cosh kz\big]+Dz \sinh kz ,
\end{equation*}
\begin{equation*}
f'(0)=0,\qquad f'''(0)=-2k^{3}C .
\end{equation*}
Hence

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)
          =-2\mu k^{2}C=\rho g e\cos kx ,
\end{equation*}
i.e. with the buoyancy restoring stress written as $\Delta\rho g e$

\begin{equation*}
\Delta\rho g e_{s}=-2\mu k^{2}C ,\qquad 
e_{s}\propto\cos kx ,
\end{equation*}
the steady topography being $90^{\circ}$ out of phase with the
imposed $\sin kx$ basal traction.  On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h), \qquad 
\sigma_{xz}(h)=S_{0}\sin kx ,
\end{equation*}
i.e.

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0},\qquad 
f'''(h)=3k^{2}f'(h) .
\end{equation*}
With the above $f$

\begin{equation*}
f'(z)=-k^{2}Cz\sinh kz+D\sinh kz+ Dkz\cosh kz ,
\end{equation*}
\begin{equation*}
f'''(z)=-2k^{3}C\cosh kz-k^{4}Cz\sinh kz
       +3k^{2}D\sinh kz+k^{3}Dz\cosh kz .
\end{equation*}
$f'''(h)=3k^{2}f'(h)$ gives

\begin{equation*}
C\big[kh\sinh kh-\cosh kh\big]=Dh\cosh kh ,\qquad
D=C\,\frac{kh\sinh kh-\cosh kh}{h\cosh kh},
\end{equation*}
and

\begin{equation*}
f''+k^{2}f=2k\Big[ D\cosh kz+Dkz\sinh kz-
k^{2}Cz\cosh kz\Big] .
\end{equation*}
Hence

\begin{equation*}
\Big[f''+k^{2}f\Big]_{h}
   =-\,\frac{2kC}{h\cosh kh}\Big[k^{2}h^{2}+\cosh^{2}kh\Big],
\end{equation*}
so that

\begin{equation*}
S_{0}
   =\mu\Big[f''+k^{2}f\Big]_{h}
   =-\frac{2\mu kC}{h\cosh kh}\Big[k^{2}h^{2}+\cosh^{2}kh\Big],
\end{equation*}
\begin{equation*}
C=-\frac{S_{0}h\cosh kh}
        {2\mu k\big[k^{2}h^{2}+\cosh^{2}kh\big]}\; .
\end{equation*}
Using $\Delta\rho g e_{s}=-2\mu k^{2}C$ the viscosity cancels in the
steady Stokes balance and

\begin{equation*}
\Delta\rho g e_{s}
   =\frac{S_{0}kh\cosh kh}
          {k^{2}h^{2}+\cosh^{2}kh} ,
\end{equation*}
i.e. up to the conventional $\sin kx\leftrightarrow\cos kx$ sign

\begin{equation*}
e_{s}(x)=\chi(kh)\,\frac{S_{0}}{\Delta\rho g}\cos kx ,\qquad
e_{s}=-\chi\frac{S_{0}}{\Delta\rho g}
\end{equation*}
with the magnitude transfer function

\begin{equation*}
\;\chi(kh)=\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
        =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}>0\;,
\end{equation*}
which is viscosity independent.  In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that on the long wave lubrication scale

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad 
|\chi_{0}|\simeq kh ,
\end{equation*}
the well known $O(kh)$ viscous dynamic topography, $e_{s}\propto-
\cos kx$ for a $+ \sin kx$ basal shear.  For $kh=O(1)$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\approx0.46$ and
$\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  With the usual
$\rho\to\Delta\rho$ identification this is the quoted
$e_{s}=\chi S_{0}/\rho g$ steady amplitude, the minus sign being the
$90^{\circ}$ phase shift between the imposed basal shear and the
$\cos kx$ topography.  With the magnitude convention the thin-plate
limit is $|\chi_{0}|\approx kh$, i.e. $e_{s}\approx kh\,S_{0}/
\Delta\rho g$, the usual $O(kh)$ viscous plate response. ∎

