\end{equation*}
the topography being $90^{\circ}$ out of phase with the imposed
$\sin kx$ basal shear, $e\propto-\cos kx$.

On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad
\sigma_{xz}(h)=S_{0}\sin kx\iff\mu\big[f''+k^{2}f\big]_{h}=S_{0},
\tag{2}
\end{equation*}
and

\begin{equation*}
f''+k^{2}f=2k\Big[Bkh\cosh kz+D\cosh kz+Dkh\sinh kz\Big].
\end{equation*}
$f'''(h)=3k^{2}f'(h)$ gives

\begin{equation*}
B\big[\cosh kh-kh\sinh kh\big]=khD\cosh kh,
\qquad 
D=B\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh},
\tag{3}
\end{equation*}
so that

\begin{equation*}
\mu\big[f''+k^{2}f\big]_{h}
 =2\mu k\Big[Bkh\cosh kh+D\cosh kh+Dkh\sinh kh\Big]
 =2\mu kB\,\frac{k^{2}h^{2}+\cosh^{2}kh}{h\cosh kh}=S_{0}.
\end{equation*}
Eliminating $B$ between (1) and the last relation the viscosity
cancels in the steady Stokes balance and

\begin{equation*}
\Delta\rho g\,e_{s}=2\mu kB
   =S_{0}\,
     \frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}\;,
\end{equation*}
i.e. in magnitude

\begin{equation*}
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}>0,
\end{equation*}
and with the usual upward positive convention

\begin{equation*}
e(x)=-\,\chi(kh)\frac{S_{0}}{\Delta\rho g}\cos kx ,
\end{equation*}
so that the $\sin kx$ basal shear produces a $\cos kx$ topography in
quadrature and anti-phase, $e_{s}=-\chi S_{0}/\Delta\rho g$ signed,
$|e_{s}|=\chi S_{0}/\Delta\rho g$.
In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that in the long wave lubrication, thin-plate limit

\begin{equation*}
\chi_{0}\simeq kh,\qquad 
|e_{s}|\simeq kh\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar $O(kh)$ viscosity independent viscous dynamic topography,
$\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$, e.g. $\chi(1)=\cosh1/
\big[1+\cosh^{2}1\big]\approx0.46$.  With the notation of the statement
$\rho\to\Delta\rho$ this is $e_{s}= \chi S_{0}/\rho g$ up to the
inessential $-$ sign.  The $\,kh\sinh kh/[\cosh^{2}kh+k^{2}h^{2}]$ forms
are the $u_{z}(h)=0$, $f(h)=0$ impermeable base limit; with the stated
$\sigma_{zz}(h)=0$, $\sigma_{xz}(h)=S_{0}$ traction free base the base
is free to move vertically, $u_{z}(h)\neq0$, and the cosh-numerator
transfer function above is the steady, viscosity independent response.
This is normally quoted in the thin plate limit as
$e_{s}\approx kh\,S_{0}/\Delta\rho g$ with $|\chi_{0}|\simeq kh$. ∎

public_text.3:
With the $k$ mode

$\psi(x,z)=f(z)\sin kx$, $u_{x}=f'\sin kx$, $u_{z}=-k f\cos kx$,
$(D^{2}-k^{2})^{2}f=0$

\begin{equation*}
\sigma_{xz}=\mu\!\left[f''+k^{2}f\right]\sin kx ,\qquad
\sigma_{zz}= \mu\!\left[k^{-1}f'''-3k f'\right]\cos kx ,
\end{equation*}
the rigid lid is $u_{x}(0)=0$, i.e. $f'(0)=0$, and in the steady state
$\dot e=u_{z}(0)=-k f(0)=0$, i.e.

\begin{equation*}
f(0)=f'(0)=0 ,
\end{equation*}
so that with $f(0)=f'(0)=0$

\begin{equation*}
f(z)=Bz\cosh kz+\Big[D z-\frac{B}{k}\Big]\sinh kz , 
\qquad f'''(0)=2k^{2}B ,
\end{equation*}

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
      =2\mu kB\cos kx .
\end{equation*}
The buoyancy restoring stress on the deflected top is
$\sigma_{zz}(0)=\Delta\rho g\,e\cos kx$, hence up to the
$\sin\leftrightarrow\cos$ quadrature

\begin{equation*}
\Delta\rho g\,e=2\mu kB ,\qquad 
B=\frac{\Delta\rho g\,e}{2\mu k}, \tag{1}
\end{equation*}
the topography being $90^{\circ}$ out of phase with the imposed
$\sin kx$ shear.

On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad 
\sigma_{xz}(h)=S_{0}\sin kx\iff\mu\big[f''+k^{2}f\big]_{h}=S_{0},
\end{equation*}
and with $f(0)=f'(0)=0$

\begin{equation*}
f''+k^{2}f=2k\Big[Bkh\cosh kz+D\cosh kz+Dkh\sinh kz\Big] .
\end{equation*}
$f'''(h)=3k^{2}f'(h)$ is

\begin{equation*}
B\big[\cosh kh-kh\sinh kh\big]=khD\cosh kh,
\qquad 
D=B\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh} .
\end{equation*}
Hence

\begin{equation*}
\mu\big[f''+k^{2}f\big]_{h}
 =2\mu k\Big[Bkh\cosh kh+D\cosh kh+Dkh\sinh kh\Big]=S_{0}
\end{equation*}
and on elimination of $D$

\begin{equation*}
2\mu kB\,\frac{k^{2}h^{2}+\cosh^{2}kh}{h\cosh kh}=S_{0}, \qquad
B=\frac{S_{0}h\cosh kh}{2\mu\big[k^{2}h^{2}+\cosh^{2}kh\big]} .
\end{equation*}
With (1) the viscosity cancels in the steady Stokes balance,

\begin{equation*}
\Delta\rho g\,e_{s}=2\mu kB
      =S_{0}\,\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}\; ,
\end{equation*}
i.e. in magnitude

\begin{equation*}
e_{s}=\chi(kh)\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}>0,
\end{equation*}
and with the conventional upward positive sign

\begin{equation*}
e(x)=-\,\chi(kh)\,\frac{S_{0}}{\Delta\rho g}\cos kx ,
\end{equation*}
so that the $\sin kx$ basal shear produces a $\cos kx$ topography in
anti-phase and $90^{\circ}$ out of phase.  In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
hence in the lubrication thin-plate limit

\begin{equation*}
|e_{s}|\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad |\chi_{0}|\simeq kh,
\end{equation*}
and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  For $kh=1$,
$\chi(1)=\cosh1/[1+\cosh^{2}1]\simeq0.46$, the familiar $O(kh)$
viscous dynamic topography.  The steady response is viscosity
independent.  With the notation $\rho\to\Delta\rho$ of the statement
this is $e_{s}=\chi S_{0}/\rho g$ up to the inessential $-$ sign.
The $kh\sinh kh/[\cosh^{2}kh+k^{2}h^{2}]$ form is the $u_{z}(h)=0$,
$f(h)=0$ impermeable base limit; with the stated traction conditions
$\sigma_{zz}(h)=0,\;\sigma_{xz}(h)=S_{0}\sin kx$ the base is free to
move vertically, $f(h)\ne0$, and the cosh-numerator transfer function
above is the stated steady Stokes amplitude. ∎

public_text.6:
In the $k$ sector put $\psi(x,z)=f(z)\sin kx$ so that

\begin{equation*}
u_{x}=f'\sin kx,\qquad u_{z}=-k f\cos kx,\qquad
(D^{2}-k^{2})^{2}f=0 ,
\end{equation*}

\begin{equation*}
\sigma_{xz}=\mu\bigl[f''+k^{2}f\bigr]\sin kx ,\qquad 
\sigma_{zz}=\mu\Big[k^{-1}f'''-3k f'\Big]\cos kx ,
\end{equation*}
up to the hydrostatic part.  On the rigid lid
$u_{x}(0)=0$ i.e. $f'(0)=0$ and in the steady state
$\dot e=u_{z}(0)=0$ i.e. $f(0)=0$.  With $f(0)=f'(0)=0$

\begin{equation*}
f(z)=Bz\cosh kz+\Big[D\,z-\frac{B}{k}\Big]\sinh kz ,
\end{equation*}
so that

\begin{equation*}
f'''(0)=2k^{2}B ,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=2\mu kB\cos kx .
\end{equation*}
With the isostatic buoyancy

\begin{equation*}
\sigma_{zz}(0)=\Delta\rho g\,e\cos kx
\end{equation*}
\begin{equation*}
\Delta\rho g\,e_{s}=2\mu kB ,\qquad 
B=\frac{\Delta\rho g\,e_{s}}{2\mu k}\;,
\tag{1}
\end{equation*}
the topography being $90^{\circ}$ out of phase with the imposed
$\sin kx$ shear,

\begin{equation*}
e(x)\propto \cos kx ,\qquad u_{z}(0)=\dot e=0\;{\rm in\;the\;steady
\;state}.
\end{equation*}

On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff f'''(h)=3k^{2}f'(h),\qquad
\sigma_{xz}(h)=S_{0}\sin kx\iff 
\mu\bigl[f''+k^{2}f\bigr]_{h}=S_{0} .
\end{equation*}
Now

\begin{equation*}
f''+k^{2}f=2k\Big[D\cosh kz+kz\bigl(B\cosh kz+D\sinh kz\bigr)\Big],
\end{equation*}
and $f'''(h)=3k^{2}f'(h)$ gives

\begin{equation*}
B\cosh kh-kh\,D\cosh kh=kh\,B\sinh kh ,
\qquad
D=B\,\frac{\cosh kh-kh\sinh kh}{kh\cosh kh}\;,
\end{equation*}
so that

\begin{equation*}
\bigl[f''+k^{2}f\bigr]_{h}=
\frac{2B}{h\cosh kh}\,\Big[\cosh^{2}kh+k^{2}h^{2}\Big] .
\end{equation*}
Hence

\begin{equation*}
S_{0}= \mu\bigl[f''+k^{2}f\bigr]_{h}
      =\frac{2\mu B}{h\cosh kh}\Big[\cosh^{2}kh+k^{2}h^{2}\Big] .
\tag{2}
\end{equation*}
Eliminating $B$ between (1) and (2) the viscosity drops out of the
steady Stokes balance and

\begin{equation*}
\Delta\rho g\,e_{s}=S_{0}\,
\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}\;,
\end{equation*}
i.e. with the conventional upward positive sign

\begin{equation*}
e(x)=-\,\chi(kh)\,\frac{S_{0}}{\Delta\rho g}\cos kx ,
\end{equation*}
the $-\,\cos kx$ topography being $90^{\circ}$ and anti-phase to the
imposed $\tau_{b}=S_{0}\sin kx$ basal shear.  In magnitude

\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}
       =\Big[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Big]^{-1}>0,
\end{equation*}
which is viscosity independent.  In particular

\begin{equation*}
\chi(kh)=\frac{kh}{1+k^{2}h^{2}}+O(k^{4}h^{4}),\qquad kh\ll1,
\end{equation*}
so that in the long–wave lubrication, thin–plate limit

\begin{equation*}
\chi_{0}\simeq kh,\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}, 
\end{equation*}
and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  For $kh=1$
$\chi(1)=\cosh1/\!\left[1+\cosh^{2}1\right]\approx0.46$.
With the usual sign convention $e_{s}=-\chi S_{0}/\Delta\rho g$ for the
$\sin kx$ basal traction; the magnitude quoted above is the usual
$|e_{s}|=\chi S_{0}/\Delta\rho g$ viscous dynamic topography, with the
$\rho\to \Delta\rho $ isostatic replacement.  The long wave form
$|e_{s}|\approx kh\,S_{0}/\Delta\rho g$, i.e. $|\chi_{0}|\approx kh$, is
the familiar $O(kh)$ viscous plate response.  The
$kh\sinh kh/[\cosh^{2}kh+k^{2}h^{2}]$ form is the $u_{z}(h)=0$,
$f(h)=0$ impermeable–base limit. ∎
